import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getRecipeFromIngredients = async (ingredients: string[]) => {
  const prompt = `Generate a healthy, delicious recipe using primarily these local market ingredients: ${ingredients.join(', ')}. Include a title, prep time, difficulty, and clear steps.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            prepTime: { type: Type.STRING },
            difficulty: { type: Type.STRING },
            ingredients: { 
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            instructions: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            nutritionTip: { type: Type.STRING }
          },
          required: ['title', 'prepTime', 'difficulty', 'ingredients', 'instructions']
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Error generating recipe:", error);
    return null;
  }
};

export const getSeasonalAdvice = async (month: string) => {
  const prompt = `What are the top 3 items to buy at a farmers market in ${month}? Provide the items and a brief "why" for each. Also include one sustainability tip for market shopping.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            advice: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  reason: { type: Type.STRING }
                }
              }
            },
            sustainabilityTip: { type: Type.STRING }
          }
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Error fetching seasonal advice:", error);
    return null;
  }
};

