import React, { useState } from 'react';
import { getRecipeFromIngredients } from '../services/geminiService';
import { PRODUCTS } from '../constants';

const AIKitchen: React.FC = () => {
  const [selectedIngredients, setSelectedIngredients] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [recipe, setRecipe] = useState<any>(null);

  const toggleIngredient = (name: string) => {
    setSelectedIngredients(prev => 
      prev.includes(name) ? prev.filter(i => i !== name) : [...prev, name]
    );
  };

  const handleGenerate = async () => {
    if (selectedIngredients.length === 0) return;
    setLoading(true);
    setRecipe(null);
    const result = await getRecipeFromIngredients(selectedIngredients);
    setRecipe(result);
    setLoading(false);
  };

  return (
    <div className="space-y-8">
      <div className="bg-white rounded-3xl p-8 border border-stone-200 shadow-sm">
        <div className="flex items-center gap-4 mb-6">
          <div className="bg-amber-100 p-3 rounded-2xl">
            <i className="fa-solid fa-wand-sparkles text-2xl text-amber-600"></i>
          </div>
          <div>
            <h2 className="text-2xl font-bold text-stone-800">Market-to-Table AI</h2>
            <p className="text-stone-500">Pick what you bought today, we'll suggest a recipe.</p>
          </div>
        </div>

        <div className="flex flex-wrap gap-2 mb-8">
          {PRODUCTS.map(p => (
            <button
              key={p.id}
              onClick={() => toggleIngredient(p.name)}
              className={`px-4 py-2 rounded-full text-sm font-bold transition-all border ${
                selectedIngredients.includes(p.name)
                  ? 'bg-emerald-600 text-white border-emerald-600'
                  : 'bg-white text-stone-600 border-stone-200 hover:border-emerald-300'
              }`}
            >
              {p.name}
            </button>
          ))}
        </div>

        <button
          onClick={handleGenerate}
          disabled={loading || selectedIngredients.length === 0}
          className={`w-full py-4 rounded-2xl font-bold text-lg transition-all flex items-center justify-center gap-3 ${
            loading || selectedIngredients.length === 0
              ? 'bg-stone-100 text-stone-400 cursor-not-allowed'
              : 'bg-emerald-600 text-white hover:bg-emerald-700 shadow-xl shadow-emerald-100'
          }`}
        >
          {loading ? (
            <><i className="fa-solid fa-spinner animate-spin"></i> Generating...</>
          ) : (
            <><i className="fa-solid fa-utensils"></i> Generate Recipe</>
          )}
        </button>
      </div>

      {loading && (
        <div className="bg-white rounded-3xl p-12 border border-stone-200 text-center animate-pulse">
          <i className="fa-solid fa-mortar-pestle text-4xl text-emerald-200 mb-4 block"></i>
          <p className="text-stone-400 font-medium">Mixing local flavors and culinary inspiration...</p>
        </div>
      )}

      {recipe && (
        <div className="bg-white rounded-3xl border border-stone-200 shadow-xl overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="bg-emerald-50 px-8 py-6 border-b border-emerald-100 flex justify-between items-center">
            <h3 className="text-2xl font-bold text-emerald-900">{recipe.title}</h3>
            <div className="flex gap-4">
              <span className="text-xs font-bold text-emerald-700 bg-white px-3 py-1 rounded-full shadow-sm">
                <i className="fa-regular fa-clock mr-1"></i> {recipe.prepTime}
              </span>
              <span className="text-xs font-bold text-emerald-700 bg-white px-3 py-1 rounded-full shadow-sm">
                <i className="fa-solid fa-fire-burner mr-1"></i> {recipe.difficulty}
              </span>
            </div>
          </div>

          <div className="p-8 grid grid-cols-1 md:grid-cols-3 gap-10">
            <div>
              <h4 className="font-bold text-stone-800 mb-4 uppercase tracking-wider text-sm flex items-center gap-2">
                <i className="fa-solid fa-list-check text-emerald-500"></i> Ingredients
              </h4>
              <ul className="space-y-3">
                {recipe.ingredients.map((ing: string, i: number) => (
                  <li key={i} className="text-stone-600 text-sm flex items-start gap-2">
                    <span className="text-emerald-500 font-bold">•</span>
                    {ing}
                  </li>
                ))}
              </ul>
            </div>

            <div className="md:col-span-2">
              <h4 className="font-bold text-stone-800 mb-4 uppercase tracking-wider text-sm flex items-center gap-2">
                <i className="fa-solid fa-stairs text-emerald-500"></i> Instructions
              </h4>
              <ol className="space-y-6">
                {recipe.instructions.map((step: string, i: number) => (
                  <li key={i} className="flex gap-4">
                    <span className="bg-stone-100 text-stone-400 w-6 h-6 rounded-full flex items-center justify-center text-[10px] font-bold flex-shrink-0">
                      {i + 1}
                    </span>
                    <p className="text-stone-600 text-sm leading-relaxed">{step}</p>
                  </li>
                ))}
              </ol>

              {recipe.nutritionTip && (
                <div className="mt-8 p-6 bg-amber-50 rounded-2xl border border-amber-100">
                  <p className="text-xs font-bold text-amber-800 uppercase tracking-widest mb-2 flex items-center gap-2">
                    <i className="fa-solid fa-lightbulb"></i> Chef's Nutrition Tip
                  </p>
                  <p className="text-sm text-amber-900 leading-relaxed italic">"{recipe.nutritionTip}"</p>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AIKitchen;

