              <div className="bg-emerald-50 rounded-3xl p-8 border-2 border-dashed border-emerald-200 flex flex-col items-center justify-center text-center group cursor-pointer hover:bg-emerald-100 transition-colors">
                <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mb-4 shadow-sm group-hover:scale-110 transition-transform">
