import React, { useState } from 'react';
import { getRecipeFromIngredients } from '../services/geminiService';
import { PRODUCTS } from '../constants';

const AIKitchen: React.FC = () => {
  const [selectedIngredients, setSelectedIngredients] = useState<string[]>([]);
  const [customPrompt, setCustomPrompt] = useState("");
  const [loading, setLoading] = useState(false);
  const [recipe, setRecipe] = useState<any>(null);

  const toggleIngredient = (name: string) => {
    setSelectedIngredients(prev => 
      prev.includes(name) ? prev.filter(i => i !== name) : [...prev, name]
    );
  };

  const handleGenerate = async () => {
    // If we have custom prompt, use it, otherwise use selected ingredients
    const inputs = customPrompt.trim() !== "" ? [customPrompt] : selectedIngredients;
    if (inputs.length === 0) return;

    setLoading(true);
    setRecipe(null);
    const result = await getRecipeFromIngredients(inputs);
    setRecipe(result);
    setLoading(false);
  };

  return (
    <div className="space-y-8">
      <div className="bg-white rounded-[2rem] p-8 border border-stone-200 shadow-sm">
        <div className="flex items-center gap-4 mb-8">
          <div className="bg-amber-100 p-4 rounded-3xl">
            <i className="fa-solid fa-mortar-pestle text-3xl text-amber-600"></i>
          </div>
          <div>
            <h2 className="text-2xl font-bold text-stone-800">Mandi Recipe Helper</h2>
            <p className="text-stone-500">Tell us what you have, and we will find a recipe!</p>
          </div>
        </div>

        {/* Option 1: Select Ingredients */}
        <div className="mb-8">
          <h4 className="text-sm font-black text-stone-400 uppercase tracking-widest mb-4">Option 1: Tap what you bought</h4>
          <div className="flex flex-wrap gap-2">
            {PRODUCTS.map(p => (
              <button
                key={p.id}
                onClick={() => toggleIngredient(p.name)}
                className={`px-5 py-2.5 rounded-2xl text-sm font-bold transition-all border ${
                  selectedIngredients.includes(p.name)
                    ? 'bg-emerald-600 text-white border-emerald-600 shadow-lg shadow-emerald-100'
                    : 'bg-white text-stone-600 border-stone-200 hover:border-emerald-300'
                }`}
              >
                {p.name}
              </button>
            ))}
          </div>
        </div>

        <div className="flex items-center gap-4 mb-8">
          <div className="h-px bg-stone-100 flex-1"></div>
          <span className="text-xs font-bold text-stone-300 uppercase tracking-widest">Or</span>
          <div className="h-px bg-stone-100 flex-1"></div>
        </div>

        {/* Option 2: Custom Text Input */}
        <div className="mb-8">
          <h4 className="text-sm font-black text-stone-400 uppercase tracking-widest mb-4">Option 2: Type your own idea</h4>
          <textarea
            value={customPrompt}
            onChange={(e) => setCustomPrompt(e.target.value)}
            placeholder="Example: I have some ladyfinger (bhindi) and curd, what can I make?"
            className="w-full bg-stone-50 border border-stone-200 rounded-3xl px-6 py-4 text-sm focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none min-h-[100px] transition-all"
          />
        </div>

        <button
          onClick={handleGenerate}
          disabled={loading || (selectedIngredients.length === 0 && customPrompt.trim() === "")}
          className={`w-full py-5 rounded-2xl font-bold text-lg transition-all flex items-center justify-center gap-3 ${
            loading || (selectedIngredients.length === 0 && customPrompt.trim() === "")
              ? 'bg-stone-100 text-stone-400 cursor-not-allowed'
              : 'bg-emerald-600 text-white hover:bg-emerald-700 shadow-xl shadow-emerald-100'
          }`}
        >
          {loading ? (
            <><i className="fa-solid fa-spinner animate-spin"></i> Finding Best Recipe...</>
          ) : (
            <><i className="fa-solid fa-fire-burner"></i> Get Indian Style Recipe</>
          )}
        </button>
      </div>

      {loading && (
        <div className="bg-white rounded-[2rem] p-16 border border-stone-200 text-center animate-pulse">
          <i className="fa-solid fa-kitchen-set text-6xl text-emerald-200 mb-6 block"></i>
          <p className="text-stone-400 font-bold text-xl">Cooking up ideas for your meal...</p>
        </div>
      )}

      {recipe && (
        <div className="bg-white rounded-[2rem] border border-stone-200 shadow-2xl overflow-hidden animate-in fade-in slide-in-from-bottom-8 duration-500">
          <div className="bg-emerald-50 px-8 py-8 border-b border-emerald-100 flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div>
              <span className="bg-emerald-200 text-emerald-800 text-[10px] font-black px-2 py-0.5 rounded uppercase tracking-widest mb-2 inline-block">Mandi Magic Recipe</span>
              <h3 className="text-3xl font-black text-emerald-900">{recipe.title}</h3>
            </div>
            <div className="flex gap-3">
              <span className="text-xs font-black text-emerald-700 bg-white px-4 py-2 rounded-xl shadow-sm border border-emerald-100">
                <i className="fa-regular fa-clock mr-1.5"></i> {recipe.prepTime}
              </span>
              <span className="text-xs font-black text-emerald-700 bg-white px-4 py-2 rounded-xl shadow-sm border border-emerald-100">
                {recipe.difficulty}
              </span>
            </div>
          </div>

          <div className="p-8 grid grid-cols-1 lg:grid-cols-3 gap-12">
            <div className="lg:border-r lg:border-stone-100 lg:pr-8">
              <h4 className="font-black text-stone-800 mb-6 uppercase tracking-wider text-xs flex items-center gap-2">
                <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full"></div> Items Needed
              </h4>
              <ul className="space-y-4">
                {recipe.ingredients.map((ing: string, i: number) => (
                  <li key={i} className="text-stone-600 text-sm flex items-start gap-3 bg-stone-50 p-3 rounded-xl border border-stone-100">
                    <i className="fa-solid fa-check text-emerald-500 mt-0.5 text-xs"></i>
                    {ing}
                  </li>
                ))}
              </ul>
            </div>

            <div className="lg:col-span-2">
              <h4 className="font-black text-stone-800 mb-6 uppercase tracking-wider text-xs flex items-center gap-2">
                <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full"></div> How to Cook
              </h4>
              <div className="space-y-8">
                {recipe.instructions.map((step: string, i: number) => (
                  <div key={i} className="flex gap-6 group">
                    <div className="flex-shrink-0">
                      <div className="bg-stone-900 text-white w-8 h-8 rounded-2xl flex items-center justify-center text-xs font-black shadow-lg shadow-stone-200 group-hover:scale-110 transition-transform">
                        {i + 1}
                      </div>
                      <div className="w-px h-full bg-stone-100 mx-auto mt-2"></div>
                    </div>
                    <p className="text-stone-700 text-base leading-relaxed pt-1">{step}</p>
                  </div>
                ))}
              </div>

              {recipe.nutritionTip && (
                <div className="mt-12 p-8 bg-amber-50 rounded-[2rem] border border-amber-100 relative overflow-hidden group">
                  <div className="absolute -right-4 -bottom-4 opacity-10 group-hover:scale-125 transition-transform duration-700">
                    <i className="fa-solid fa-heart-pulse text-8xl text-amber-600"></i>
                  </div>
                  <div className="relative z-10">
                    <p className="text-[10px] font-black text-amber-800 uppercase tracking-[0.2em] mb-3 flex items-center gap-2">
                      <i className="fa-solid fa-lightbulb"></i> Health Advice
                    </p>
                    <p className="text-lg text-amber-900 leading-relaxed font-medium">"{recipe.nutritionTip}"</p>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

