const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [userName, setUserName] = useState('');
  const [activeTab, setActiveTab] = useState('explore');
  const [seasonalAdvice, setSeasonalAdvice] = useState<any>(null);
  const [loadingAdvice, setLoadingAdvice] = useState(false);
  const [cart, setCart] = useState<Array<{ id: string; name: string; price: number }>>([]);
  const [showCart, setShowCart] = useState(false);
  const [showRegisterModal, setShowRegisterModal] = useState(false);
  const [showPayment, setShowPayment] = useState(false);
  const [allFarmers, setAllFarmers] = useState<Farmer[]>(FARMERS);
  const [markets, setMarkets] = useState<Market[]>(MARKETS);
  const [userLocation, setUserLocation] = useState<GeolocationPosition | null>(null);

  useEffect(() => {
    if (!isLoggedIn) return;

    // Fetch Geolocation
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setUserLocation(position);
          // Simulate recalculating distances
          setMarkets(prev => prev.map(m => ({
            ...m,
            distance: (Math.random() * 5 + 1).toFixed(1) + ' km'
          })));
        },
        (error) => console.log("Location access denied", error)
      );
    }

    const fetchAdvice = async () => {
      setLoadingAdvice(true);
      const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
      const currentMonth = monthNames[new Date().getMonth()];
      const advice = await getSeasonalAdvice(currentMonth);
      setSeasonalAdvice(advice);
      setLoadingAdvice(false);
    };
    fetchAdvice();
  }, [isLoggedIn]);

  const addToCart = (product: any) => {
    setCart(prev => [...prev, { id: product.id, name: product.name, price: product.price }]);
    const toast = document.createElement('div');
    toast.className = 'fixed bottom-20 left-1/2 -translate-x-1/2 bg-stone-900 text-white px-6 py-3 rounded-full text-sm font-bold shadow-2xl z-[100] animate-bounce';
    toast.innerText = `Added ${product.name} to bag! 🛍️`;
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 2000);
  };

  const onPaymentSuccess = () => {
    setShowPayment(false);
    setCart([]);
    setShowCart(false);
    alert(`Payment Successful! Your local farmer has been notified to pack your fresh produce. Thank you, ${userName}!`);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setUserName('');
    setCart([]);
  };

  const cartTotal = cart.reduce((sum, item) => sum + item.price, 0);

  if (!isLoggedIn) {
    return <Auth onLogin={(name) => { setUserName(name); setIsLoggedIn(true); }} />;
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'explore':
        return (
          <div className="space-y-10 pb-24 md:pb-12">
            <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
              <div className="flex-1">
                <div className="flex items-center gap-4 mb-2">
                   <h2 className="text-4xl font-extrabold text-stone-900 leading-tight">Hello, {userName}</h2>
                   <button 
                    onClick={handleLogout}
                    className="bg-stone-200 text-stone-600 hover:text-white hover:bg-red-600 px-4 py-1.5 rounded-full text-xs font-black uppercase transition-all flex items-center gap-2"
                   >
                     <i className="fa-solid fa-arrow-right-from-bracket"></i> Sign Out
                   </button>
                </div>
                <p className="text-emerald-600 font-bold text-xl mb-1">Pure & Fresh.</p>
                <div className="flex items-center gap-2 text-stone-500 font-medium">
                  {userLocation ? (
                    <><i className="fa-solid fa-location-crosshairs text-emerald-500"></i> Local Mandis nearby found.</>
                  ) : (
                    <>Buy best quality food directly from local farmers.</>
