          </div>
          <i className="fa-solid fa-shield-halved text-4xl opacity-50"></i>
        </div>

        <div className="p-8">
          {step === 1 && (
            <div className="space-y-4">
              <h3 className="font-bold text-stone-800 mb-2 text-lg">Choose Payment Method</h3>
              <button onClick={() => { setMethod('UPI'); setStep(2); }} className="w-full p-5 border-2 border-stone-100 rounded-2xl flex items-center justify-between hover:border-emerald-500 transition-all">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-blue-50 rounded-xl flex items-center justify-center">
                    <i className="fa-solid fa-mobile-screen-button text-blue-600"></i>
                  </div>
                  <span className="font-bold text-stone-700">UPI (PhonePe, GPay)</span>
                </div>
                <i className="fa-solid fa-chevron-right text-stone-300"></i>
              </button>
              <button onClick={() => { setMethod('Card'); setStep(2); }} className="w-full p-5 border-2 border-stone-100 rounded-2xl flex items-center justify-between hover:border-emerald-500 transition-all">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-purple-50 rounded-xl flex items-center justify-center">
                    <i className="fa-solid fa-credit-card text-purple-600"></i>
                  </div>
                  <span className="font-bold text-stone-700">Debit / Credit Card</span>
                </div>
                <i className="fa-solid fa-chevron-right text-stone-300"></i>
              </button>
              <button onClick={onCancel} className="w-full py-4 text-stone-400 font-bold hover:text-stone-600">Cancel</button>
            </div>
          )}

          {step === 2 && (
            <div className="space-y-6">
              <div className="flex items-center gap-3 mb-2">
                <button onClick={() => setStep(1)} className="text-stone-400 hover:text-stone-900"><i className="fa-solid fa-arrow-left"></i></button>
                <h3 className="font-bold text-stone-800 text-lg">Enter {method} Details</h3>
              </div>
              <input type="text" placeholder={method === 'UPI' ? "example@upi" : "Card Number"} className="w-full bg-stone-50 border border-stone-100 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-emerald-500" />
              <button 
                onClick={handlePay}
                className="w-full bg-emerald-600 text-white font-black py-4 rounded-2xl hover:bg-emerald-700 shadow-xl shadow-emerald-100"
              >
                Complete Payment
              </button>
            </div>
          )}

          {step === 3 && (
            <div className="text-center py-10">
              <div className="relative w-24 h-24 mx-auto mb-6">
                <div className="absolute inset-0 border-4 border-stone-100 rounded-full"></div>
                <div className="absolute inset-0 border-4 border-emerald-500 rounded-full border-t-transparent animate-spin"></div>
              </div>
              <h3 className="text-xl font-bold text-stone-800 mb-2">Processing...</h3>
              <p className="text-stone-500">Talking to your bank securely. Do not refresh.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

