  const [loadingMarkets, setLoadingMarkets] = useState(false);
  const [cart, setCart] = useState<Array<{ id: string; name: string; price: number }>>([]);
  const [showCart, setShowCart] = useState(false);
  const [showRegisterModal, setShowRegisterModal] = useState(false);
  const [showPayment, setShowPayment] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [allFarmers, setAllFarmers] = useState<Farmer[]>(FARMERS);
  const [markets, setMarkets] = useState<Market[]>(MARKETS);
  const [userLocation, setUserLocation] = useState<GeolocationPosition | null>(null);
  const [purchaseHistory, setPurchaseHistory] = useState<PurchaseHistoryItem[]>([]);

  // Dynamic User Stats
  const [userStats, setUserStats] = useState<UserStats>({
    marketsVisited: 0,
    co2SavedKg: 0,
    localEconomySupport: 0,
    badgesEarned: 0
  });

  useEffect(() => {
    if (!isLoggedIn) return;

    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        async (position) => {
          setUserLocation(position);
          setLoadingMarkets(true);
          const nearby = await getNearbyMarkets(position.coords.latitude, position.coords.longitude);
          if (nearby && Array.isArray(nearby)) setMarkets(nearby);
          setLoadingMarkets(false);
          setUserStats(prev => ({ ...prev, marketsVisited: nearby?.length || prev.marketsVisited }));
        },
        () => setLoadingMarkets(false)
      );
    }

    const fetchAdvice = async () => {
      setLoadingAdvice(true);
      const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
      const currentMonth = monthNames[new Date().getMonth()];
      const advice = await getSeasonalAdvice(currentMonth);
      setSeasonalAdvice(advice);
      setLoadingAdvice(false);
    };
    fetchAdvice();
  }, [isLoggedIn]);

  const addToCart = (product: any) => {
    setCart(prev => [...prev, { id: product.id, name: product.name, price: product.price }]);
  };

  const onPaymentSuccess = () => {
    const total = cartTotal;
    const items = cart.map(c => c.name);

    // Update Stats
    setUserStats(prev => ({
      ...prev,
      localEconomySupport: prev.localEconomySupport + total,
      co2SavedKg: prev.co2SavedKg + (total / 100 * 0.5) // Every 100 rupees saves ~0.5kg CO2
    }));

    // Update History
    const newRecord: PurchaseHistoryItem = {
      id: 'ord_' + Date.now(),
      date: new Date().toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }),
      items: items,
      total: total
    };
    setPurchaseHistory(prev => [newRecord, ...prev]);

    setShowPayment(false);
    setCart([]);
    setShowCart(false);
    alert(`Payment Successful! Your local farmer has been notified to pack your fresh produce. Thank you, ${userName}! Check 'My Progress' to see your impact.`);
  };

  const cartTotal = cart.reduce((sum, item) => sum + item.price, 0);

  const renderContent = () => {
    switch (activeTab) {
      case 'explore':
        return (
          <div className="space-y-10 pb-24 md:pb-12">
            <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
              <div className="flex-1">
                <div className="flex items-center gap-4 mb-2">
                   <h2 className="text-4xl font-extrabold text-stone-900 leading-tight">Hello, {userName}</h2>
                   <button 
                    onClick={() => setIsLoggedIn(false)}
                    className="bg-stone-200 text-stone-600 hover:text-white hover:bg-red-600 px-4 py-1.5 rounded-full text-xs font-black uppercase transition-all flex items-center gap-2"
                   >
                     Sign Out
                   </button>
                </div>
                <p className="text-emerald-600 font-bold text-xl mb-1">Fresh from the Mandi.</p>
                <div className="flex items-center gap-2 text-stone-500 font-medium h-6">
                  {loadingMarkets ? (
                    <span className="flex items-center gap-2 text-xs"><i className="fa-solid fa-spinner animate-spin"></i> Finding nearby Mandis...</span>
                  ) : userLocation ? (
                    <><i className="fa-solid fa-location-crosshairs text-emerald-500"></i> Local Mandis found.</>
                  ) : (
                    <>Browse local vegetables & farmers.</>
                  )}
                </div>
              </div>
              <div className="flex gap-4">
                <button 
                  onClick={() => setShowHistory(true)}
                  className="bg-white border border-stone-200 p-4 rounded-2xl shadow-sm hover:shadow-md transition-all text-stone-600 flex items-center gap-2 font-bold"
                >
                  <i className="fa-solid fa-clock-rotate-left"></i>
                  <span className="hidden md:inline">History</span>
                </button>
                <button 
                  onClick={() => setShowCart(!showCart)}
                  className="relative bg-white border border-stone-200 p-4 rounded-2xl shadow-sm hover:shadow-md transition-all group"
                >
                  <i className="fa-solid fa-bag-shopping text-2xl text-emerald-600"></i>
                  {cart.length > 0 && (
                    <span className="absolute -top-2 -right-2 bg-red-500 text-white text-[10px] font-bold w-6 h-6 flex items-center justify-center rounded-full border-2 border-white">
                      {cart.length}
                    </span>
                  )}
                  <span className="ml-2 font-bold text-stone-700 hidden md:inline">₹{cartTotal}</span>
                </button>
              </div>
            </header>

            {showCart && cart.length > 0 && (
              <div className="bg-white rounded-3xl p-6 border border-emerald-100 shadow-xl animate-in fade-in zoom-in duration-300">
                <div className="flex justify-between items-center mb-4">
                  <h3 className="text-xl font-bold text-stone-800">Your Fresh Bag</h3>
                  <button onClick={() => setCart([])} className="text-xs text-red-500 font-bold hover:underline">Clear</button>
                </div>
                <div className="space-y-2 mb-6">
                  {cart.map((item, idx) => (
                    <div key={idx} className="flex justify-between items-center text-sm py-2 border-b border-stone-50">
                      <span className="text-stone-600">{item.name}</span>
                      <span className="font-bold text-stone-800">₹{item.price}</span>
                    </div>
                  ))}
                  <div className="flex justify-between items-center pt-2 font-black text-lg text-emerald-700">
                    <span>Total Amount</span>
                    <span>₹{cartTotal}</span>
                  </div>
                </div>
                <button 
                  onClick={() => setShowPayment(true)}
                  className="w-full bg-emerald-600 text-white font-black py-4 rounded-2xl hover:bg-emerald-700 transition-colors shadow-lg shadow-emerald-100"
                >
                  Checkout Now
                </button>
              </div>
            )}

            <section>
              <h3 className="text-2xl font-bold text-stone-800 mb-6">Available Today</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-6">
                {PRODUCTS.map(product => (
                  <div key={product.id} className="bg-white rounded-3xl border border-stone-200 overflow-hidden group hover:shadow-xl transition-all flex flex-col">
                    <div className="h-40 overflow-hidden relative">
                      <img src={product.image} alt={product.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                    </div>
                    <div className="p-4 flex-1 flex flex-col">
                      <h4 className="font-bold text-stone-800 mb-1">{product.name}</h4>
                      <div className="flex justify-between items-center mb-4">
                        <span className="text-emerald-600 font-bold">₹{product.price}</span>
                        <span className="text-[10px] text-stone-400 font-bold uppercase">per {product.unit}</span>
                      </div>
                      <button 
                        onClick={() => addToCart(product)}
                        className="mt-auto w-full bg-emerald-50 text-emerald-700 font-bold py-2 rounded-xl text-xs hover:bg-emerald-600 hover:text-white transition-colors"
                      >
                        Add to Bag
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </section>
          </div>
        );
      case 'markets':
        return (
          <div className="space-y-8 pb-24 md:pb-12">
            <h2 className="text-3xl font-bold text-stone-900 mb-2">Nearby Local Mandi</h2>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              {markets.map(market => <MarketCard key={market.id} market={market} />)}
            </div>
          </div>
        );
      case 'farmers':
        return (
          <div className="space-y-8 pb-24 md:pb-12">
            <h2 className="text-3xl font-bold text-stone-900 mb-2">Our Kisan Community</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {allFarmers.map(farmer => <FarmerCard key={farmer.id} farmer={farmer} />)}
              <div 
                onClick={() => setShowRegisterModal(true)}
                className="bg-emerald-50 rounded-[2.5rem] p-8 border-2 border-dashed border-emerald-200 flex flex-col items-center justify-center text-center group cursor-pointer hover:bg-emerald-100 transition-colors h-full min-h-[350px]"
              >
                <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mb-4 shadow-sm group-hover:scale-110 transition-transform">
                  <i className="fa-solid fa-plus text-emerald-600 text-2xl"></i>
                </div>
                <h3 className="text-xl font-black text-emerald-900">Are you a Farmer?</h3>
                <p className="text-emerald-700 font-medium mb-6">Create your profile and start selling directly.</p>
                <button className="bg-emerald-700 text-white font-bold py-3 px-8 rounded-xl shadow-lg">Register Now</button>
              </div>
            </div>
          </div>
        );
      case 'kitchen': return <AIKitchen />;
      case 'stats': return <ImpactStats stats={userStats} />;
      default: return null;
    }
  };

  return (
    <div className="min-h-screen md:pl-64">
      <Navigation activeTab={activeTab} setActiveTab={setActiveTab} />
      <main className="max-w-7xl mx-auto p-6 md:p-12">
        {isLoggedIn ? renderContent() : <Auth onLogin={(name) => { setUserName(name); setIsLoggedIn(true); }} />}
      </main>

      {showRegisterModal && (
        <FarmerRegistration 
          onClose={() => setShowRegisterModal(false)} 
          onAdd={(newFarmer) => setAllFarmers(prev => [newFarmer, ...prev])} 
        />
      )}

      {showPayment && (
        <PaymentGateway 
          total={cartTotal} 
          onCancel={() => setShowPayment(false)} 
          onSuccess={onPaymentSuccess} 
        />
      )}

      {showHistory && (
        <HistoryModal 
          history={purchaseHistory} 
          onClose={() => setShowHistory(false)} 
        />
      )}
    </div>
  );
};

