// --- AUTH COMPONENTS ---

const Auth: React.FC<{ onLogin: (name: string) => void }> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [name, setName] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    const storedUsers = JSON.parse(localStorage.getItem('hh_users') || '[]');

    if (isLogin) {
      const user = storedUsers.find((u: any) => u.name === name && u.password === password);
      if (user) {
        onLogin(user.name);
      } else {
        setError('Wrong username or password! Please try again.');
      }
    } else {
      if (storedUsers.some((u: any) => u.name === name)) {
        setError('User already exists! Try a different name.');
      } else {
        storedUsers.push({ name, password });
        localStorage.setItem('hh_users', JSON.stringify(storedUsers));
        onLogin(name);
      }
    }
  };

  return (
    <div className="min-h-screen bg-emerald-900 flex items-center justify-center p-6">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] p-10 shadow-2xl animate-in fade-in zoom-in duration-500">
        <div className="flex flex-col items-center mb-10">
          <div className="bg-emerald-600 p-4 rounded-3xl mb-4 shadow-lg">
            <i className="fa-solid fa-leaf text-3xl text-white"></i>
          </div>
          <h1 className="text-3xl font-black text-stone-900 tracking-tight">HarvestHub</h1>
          <p className="text-stone-500 font-medium text-center">Support your local Farmers</p>
        </div>

        <form onSubmit={handleAuth} className="space-y-6">
          <div>
            <label className="block text-xs font-black text-stone-400 uppercase tracking-widest mb-2">User Name</label>
            <input 
              type="text" 
              required
              placeholder="Enter your name" 
              className="w-full bg-stone-50 border border-stone-200 rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-emerald-500"
              value={name}
              onChange={(e) => setName(e.target.value)}
            />
          </div>
          <div>
            <label className="block text-xs font-black text-stone-400 uppercase tracking-widest mb-2">Password</label>
            <input 
              type="password" 
              required
              placeholder="Create/Enter password" 
              className="w-full bg-stone-50 border border-stone-200 rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-emerald-500"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
          </div>
          {error && <p className="text-red-500 text-xs font-bold text-center">{error}</p>}
          <button 
            type="submit"
            className="w-full bg-emerald-600 text-white font-black py-4 rounded-2xl hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-100"
          >
            {isLogin ? 'Login' : 'Join HarvestHub'}
          </button>
        </form>

        <div className="mt-8 pt-8 border-t border-stone-100 text-center">
          <button 
            onClick={() => { setIsLogin(!isLogin); setError(''); }}
            className="text-emerald-600 font-black text-sm hover:underline"
          >
            {isLogin ? "Don't have an account? Sign Up" : "Already have an account? Login"}
          </button>
        </div>
      </div>
    </div>
  );
};

// --- PAYMENT GATEWAY ---

const PaymentGateway: React.FC<{ total: number; onCancel: () => void; onSuccess: () => void }> = ({ total, onCancel, onSuccess }) => {
  const [step, setStep] = useState(1);
  const [method, setMethod] = useState('');

  const handlePay = () => {
    setStep(3);
    setTimeout(() => {
      onSuccess();
    }, 3000);
  };

  return (
    <div className="fixed inset-0 bg-stone-900/80 backdrop-blur-md z-[200] flex items-center justify-center p-6">
      <div className="bg-white w-full max-w-lg rounded-[2.5rem] overflow-hidden shadow-2xl">
        <div className="bg-emerald-600 p-8 text-white flex justify-between items-center">
          <div>
            <h2 className="text-2xl font-black">Secure Checkout</h2>
            <p className="text-emerald-100 font-medium">Order Total: ₹{total}</p>
          </div>
          <i className="fa-solid fa-shield-halved text-4xl opacity-50"></i>
        </div>

        <div className="p-8">
          {step === 1 && (
            <div className="space-y-4">
              <h3 className="font-bold text-stone-800 mb-2 text-lg">Choose Payment Method</h3>
              <button onClick={() => { setMethod('UPI'); setStep(2); }} className="w-full p-5 border-2 border-stone-100 rounded-2xl flex items-center justify-between hover:border-emerald-500 transition-all">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-blue-50 rounded-xl flex items-center justify-center">
                    <i className="fa-solid fa-mobile-screen-button text-blue-600"></i>
                  </div>
                  <span className="font-bold text-stone-700">UPI (PhonePe, GPay)</span>
                </div>
                <i className="fa-solid fa-chevron-right text-stone-300"></i>
              </button>
              <button onClick={() => { setMethod('Card'); setStep(2); }} className="w-full p-5 border-2 border-stone-100 rounded-2xl flex items-center justify-between hover:border-emerald-500 transition-all">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-purple-50 rounded-xl flex items-center justify-center">
                    <i className="fa-solid fa-credit-card text-purple-600"></i>
                  </div>
                  <span className="font-bold text-stone-700">Debit / Credit Card</span>
                </div>
                <i className="fa-solid fa-chevron-right text-stone-300"></i>
              </button>
              <button onClick={onCancel} className="w-full py-4 text-stone-400 font-bold hover:text-stone-600">Cancel</button>
            </div>
          )}

          {step === 2 && (
            <div className="space-y-6">
              <div className="flex items-center gap-3 mb-2">
                <button onClick={() => setStep(1)} className="text-stone-400 hover:text-stone-900"><i className="fa-solid fa-arrow-left"></i></button>
                <h3 className="font-bold text-stone-800 text-lg">Enter {method} Details</h3>
              </div>
              <input type="text" placeholder={method === 'UPI' ? "example@upi" : "Card Number"} className="w-full bg-stone-50 border border-stone-100 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-emerald-500" />
              <button 
                onClick={handlePay}
                className="w-full bg-emerald-600 text-white font-black py-4 rounded-2xl hover:bg-emerald-700 shadow-xl shadow-emerald-100"
              >
                Complete Payment
              </button>
            </div>
          )}

          {step === 3 && (
            <div className="text-center py-10">
              <div className="relative w-24 h-24 mx-auto mb-6">
                <div className="absolute inset-0 border-4 border-stone-100 rounded-full"></div>
                <div className="absolute inset-0 border-4 border-emerald-500 rounded-full border-t-transparent animate-spin"></div>
              </div>
              <h3 className="text-xl font-bold text-stone-800 mb-2">Processing...</h3>
              <p className="text-stone-500">Talking to your bank securely. Do not refresh.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

