  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [userName, setUserName] = useState('');
  const [activeTab, setActiveTab] = useState('explore');
  const [loadingMarkets, setLoadingMarkets] = useState(false);
  const [cart, setCart] = useState<Array<{ id: string; name: string; price: number }>>([]);
  const [showCart, setShowCart] = useState(false);
  const [showRegisterModal, setShowRegisterModal] = useState(false);
  const [showPayment, setShowPayment] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [allFarmers, setAllFarmers] = useState<Farmer[]>(FARMERS);
  const [markets, setMarkets] = useState<Market[]>(MARKETS);
  const [userLocation, setUserLocation] = useState<GeolocationPosition | null>(null);
  const [purchaseHistory, setPurchaseHistory] = useState<PurchaseHistoryItem[]>([]);
  const [userStats, setUserStats] = useState<UserStats>({
    marketsVisited: 0,
    co2SavedKg: 0,
    localEconomySupport: 0,
    badgesEarned: 0
  });

  useEffect(() => {
    if (!isLoggedIn) return;

    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        async (position) => {
          setUserLocation(position);
          setLoadingMarkets(true);
          const nearby = await getNearbyMarkets(position.coords.latitude, position.coords.longitude);
          if (nearby && Array.isArray(nearby)) setMarkets(nearby);
          setLoadingMarkets(false);
          setUserStats(prev => ({ ...prev, marketsVisited: nearby?.length || prev.marketsVisited }));
        },
        () => setLoadingMarkets(false)
      );
    }
  }, [isLoggedIn]);

  const addToCart = (product: any) => {
    setCart(prev => [...prev, { id: product.id, name: product.name, price: product.price }]);
  };

  const onPaymentSuccess = () => {
    const total = cartTotal;
    const items = cart.map(c => c.name);

    setUserStats(prev => ({
      ...prev,
      localEconomySupport: prev.localEconomySupport + total,
      co2SavedKg: prev.co2SavedKg + (total / 100 * 0.4) 
    }));

    const newRecord: PurchaseHistoryItem = {
      id: 'ord_' + Date.now(),
      date: new Date().toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }),
      items: items,
      total: total
    };
    setPurchaseHistory(prev => [newRecord, ...prev]);

    setShowPayment(false);
    setCart([]);
    setShowCart(false);
    alert(`Success! ₹${total} paid to our Farmer partners. Thank you for buying local!`);
  };

  const cartTotal = cart.reduce((sum, item) => sum + item.price, 0);

  const renderContent = () => {
    switch (activeTab) {
      case 'explore':
        return (
          <div className="space-y-10 pb-24 md:pb-12">
            <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
              <div className="flex-1">
                <div className="flex items-center gap-4 mb-2">
                   <h2 className="text-4xl font-extrabold text-stone-900 leading-tight">Hello, {userName}</h2>
                   <button 
                    onClick={() => setIsLoggedIn(false)}
                    className="bg-stone-200 text-stone-600 hover:text-white hover:bg-red-600 px-4 py-1.5 rounded-full text-xs font-black uppercase transition-all flex items-center gap-2"
                   >
                     Logout
                   </button>
                </div>
                <p className="text-emerald-600 font-bold text-xl mb-1">Fresh from local farms.</p>
                <div className="flex items-center gap-2 text-stone-500 font-medium h-6">
                  {loadingMarkets ? (
                    <span className="flex items-center gap-2 text-xs"><i className="fa-solid fa-spinner animate-spin"></i> Checking nearby Mandis...</span>
                  ) : userLocation ? (
                    <><i className="fa-solid fa-location-crosshairs text-emerald-500"></i> Mandis found in your area.</>
                  ) : (
                    <>Buy fresh directly from Indian Kisans.</>
                  )}
                </div>
              </div>
              <div className="flex gap-4">
                <button 
                  onClick={() => setShowHistory(true)}
                  className="bg-white border border-stone-200 p-4 rounded-2xl shadow-sm hover:shadow-md transition-all text-stone-600 flex items-center gap-2 font-bold"
                >
                  <i className="fa-solid fa-clock-rotate-left"></i>
                  <span className="hidden md:inline">History</span>
                </button>
                <button 
                  onClick={() => setShowCart(!showCart)}
                  className="relative bg-white border border-stone-200 p-4 rounded-2xl shadow-sm hover:shadow-md transition-all group"
                >
                  <i className="fa-solid fa-bag-shopping text-2xl text-emerald-600"></i>
                  {cart.length > 0 && (
                    <span className="absolute -top-2 -right-2 bg-red-500 text-white text-[10px] font-bold w-6 h-6 flex items-center justify-center rounded-full border-2 border-white">
                      {cart.length}
                    </span>
                  )}
                  <span className="ml-2 font-bold text-stone-700 hidden md:inline">₹{cartTotal}</span>
                </button>
              </div>
            </header>

            <section>
              <h3 className="text-2xl font-bold text-stone-800 mb-6">Mandi Favorites</h3>
              <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-5 gap-6">
                {PRODUCTS.map(product => (
                  <div key={product.id} className="bg-white rounded-[2rem] border border-stone-200 overflow-hidden group hover:shadow-xl transition-all flex flex-col">
                    <div className="h-40 overflow-hidden relative">
                      <img src={product.image} alt={product.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                    </div>
                    <div className="p-5 flex-1 flex flex-col">
                      <h4 className="font-black text-stone-800 mb-1">{product.name}</h4>
                      <div className="flex justify-between items-center mb-4">
                        <span className="text-emerald-600 font-black">₹{product.price}</span>
                        <span className="text-[10px] text-stone-400 font-bold">/{product.unit}</span>
                      </div>
                      <button 
                        onClick={() => addToCart(product)}
                        className="mt-auto w-full bg-emerald-50 text-emerald-700 font-black py-2.5 rounded-xl text-xs hover:bg-emerald-600 hover:text-white transition-all"
                      >
                        Add to Bag
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </section>
          </div>
        );
      case 'markets':
        return (
          <div className="space-y-8 pb-24 md:pb-12">
            <h2 className="text-3xl font-black text-stone-900 mb-2">Nearby Local Mandi</h2>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              {markets.map(market => <MarketCard key={market.id} market={market} />)}
            </div>
          </div>
        );
      case 'farmers':
        return (
          <div className="space-y-8 pb-24 md:pb-12">
            <h2 className="text-3xl font-black text-stone-900 mb-2">Our Kisan Community</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {allFarmers.map(farmer => <FarmerCard key={farmer.id} farmer={farmer} />)}
              <div 
                onClick={() => setShowRegisterModal(true)}
                className="bg-emerald-50 rounded-[2.5rem] p-8 border-2 border-dashed border-emerald-200 flex flex-col items-center justify-center text-center group cursor-pointer hover:bg-emerald-100 transition-colors h-full min-h-[350px]"
              >
                <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mb-4 shadow-sm group-hover:scale-110 transition-transform">
                  <i className="fa-solid fa-plus text-emerald-600 text-2xl"></i>
                </div>
                <h3 className="text-xl font-black text-emerald-900">Are you a Farmer?</h3>
                <p className="text-emerald-700 font-medium mb-6">Create your profile and start selling directly.</p>
                <button className="bg-emerald-700 text-white font-bold py-3 px-8 rounded-xl shadow-lg">Join Community</button>
              </div>
            </div>
          </div>
        );
      case 'kitchen': return <AIKitchen />;
      case 'stats': return <ImpactStats stats={userStats} />;
      default: return null;
    }
  };

  if (!isLoggedIn) {
    return <Auth onLogin={(name) => { setUserName(name); setIsLoggedIn(true); }} />;
  }

  return (
    <div className="min-h-screen md:pl-64">
      <Navigation activeTab={activeTab} setActiveTab={setActiveTab} />
      <main className="max-w-7xl mx-auto p-6 md:p-12">
        {renderContent()}
      </main>

      {showRegisterModal && (
        <FarmerRegistration 
          onClose={() => setShowRegisterModal(false)} 
          onAdd={(newFarmer) => setAllFarmers(prev => [newFarmer, ...prev])} 
        />
      )}

      {showPayment && (
        <PaymentGateway 
          total={cartTotal} 
          onCancel={() => setShowPayment(false)} 
          onSuccess={onPaymentSuccess} 
        />
      )}

      {showHistory && (
        <HistoryModal 
          history={purchaseHistory} 
          onClose={() => setShowHistory(false)} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import Navigation from './components/Navigation';
import MarketCard from './components/MarketCard';
import FarmerCard from './components/FarmerCard';
import ImpactStats from './components/ImpactStats';
import AIKitchen from './components/AIKitchen';
import { MARKETS, FARMERS, PRODUCTS } from './constants';
import { getSeasonalAdvice, getNearbyMarkets } from './services/geminiService';
import { Farmer, Market, UserStats, PurchaseHistoryItem, Product } from './types';

// --- AUTH COMPONENTS ---

const Auth: React.FC<{ onLogin: (name: string) => void }> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [name, setName] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    const storedUsers = JSON.parse(localStorage.getItem('hh_users') || '[]');

    if (isLogin) {
      const user = storedUsers.find((u: any) => u.name === name && u.password === password);
      if (user) {
        onLogin(user.name);
      } else {
        setError('Wrong username or password! Please try again.');
      }
    } else {
      if (storedUsers.some((u: any) => u.name === name)) {
        setError('User already exists! Try a different name.');
      } else {
        storedUsers.push({ name, password });
        localStorage.setItem('hh_users', JSON.stringify(storedUsers));
        onLogin(name);
      }
    }
  };

  return (
    <div className="fixed inset-0 bg-emerald-900 flex items-center justify-center p-6 z-[999]">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] p-10 shadow-2xl animate-in fade-in zoom-in duration-500">
        <div className="flex flex-col items-center mb-10">
          <div className="bg-emerald-600 p-4 rounded-3xl mb-4 shadow-lg">
            <i className="fa-solid fa-leaf text-3xl text-white"></i>
          </div>
          <h1 className="text-3xl font-black text-stone-900 tracking-tight">HarvestHub</h1>
          <p className="text-stone-500 font-medium text-center">Support your local Farmers</p>
        </div>

        <form onSubmit={handleAuth} className="space-y-6">
          <div>
            <label className="block text-xs font-black text-stone-400 uppercase tracking-widest mb-2">User Name</label>
            <input 
              type="text" 
              required
              placeholder="Enter your name" 
              className="w-full bg-stone-50 border border-stone-200 rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-emerald-500"
              value={name}
              onChange={(e) => setName(e.target.value)}
            />
          </div>
          <div>
            <label className="block text-xs font-black text-stone-400 uppercase tracking-widest mb-2">Password</label>
            <input 
              type="password" 
              required
              placeholder="Create/Enter password" 
              className="w-full bg-stone-50 border border-stone-200 rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-emerald-500"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
          </div>
          {error && <p className="text-red-500 text-xs font-bold text-center">{error}</p>}
          <button 
            type="submit"
            className="w-full bg-emerald-600 text-white font-black py-4 rounded-2xl hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-100"
          >
            {isLogin ? 'Login' : 'Join HarvestHub'}
          </button>
        </form>

        <div className="mt-8 pt-8 border-t border-stone-100 text-center">
          <button 
            onClick={() => { setIsLogin(!isLogin); setError(''); }}
            className="text-emerald-600 font-black text-sm hover:underline"
          >
            {isLogin ? "Don't have an account? Sign Up" : "Already have an account? Login"}
          </button>
        </div>
      </div>
    </div>
  );
};

// --- PAYMENT GATEWAY ---

const PaymentGateway: React.FC<{ total: number; onCancel: () => void; onSuccess: () => void }> = ({ total, onCancel, onSuccess }) => {
  const [step, setStep] = useState(1);
  const [method, setMethod] = useState('');

  const handlePay = () => {
    setStep(3);
    setTimeout(() => {
      onSuccess();
    }, 3000);
  };

  return (
    <div className="fixed inset-0 bg-stone-900/80 backdrop-blur-md z-[200] flex items-center justify-center p-6">
      <div className="bg-white w-full max-w-lg rounded-[2.5rem] overflow-hidden shadow-2xl">
        <div className="bg-emerald-600 p-8 text-white flex justify-between items-center">
          <div>
            <h2 className="text-2xl font-black">Secure Checkout</h2>
            <p className="text-emerald-100 font-medium">Order Total: ₹{total}</p>
          </div>
          <i className="fa-solid fa-shield-halved text-4xl opacity-50"></i>
        </div>

        <div className="p-8">
          {step === 1 && (
            <div className="space-y-4">
              <h3 className="font-bold text-stone-800 mb-2 text-lg">Choose Payment Method</h3>
              <button onClick={() => { setMethod('UPI'); setStep(2); }} className="w-full p-5 border-2 border-stone-100 rounded-2xl flex items-center justify-between hover:border-emerald-500 transition-all">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-blue-50 rounded-xl flex items-center justify-center">
                    <i className="fa-solid fa-mobile-screen-button text-blue-600"></i>
                  </div>
                  <span className="font-bold text-stone-700">UPI (PhonePe, GPay)</span>
                </div>
                <i className="fa-solid fa-chevron-right text-stone-300"></i>
              </button>
              <button onClick={() => { setMethod('Card'); setStep(2); }} className="w-full p-5 border-2 border-stone-100 rounded-2xl flex items-center justify-between hover:border-emerald-500 transition-all">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-purple-50 rounded-xl flex items-center justify-center">
                    <i className="fa-solid fa-credit-card text-purple-600"></i>
                  </div>
                  <span className="font-bold text-stone-700">Debit / Credit Card</span>
                </div>
                <i className="fa-solid fa-chevron-right text-stone-300"></i>
              </button>
              <button onClick={onCancel} className="w-full py-4 text-stone-400 font-bold hover:text-stone-600">Cancel</button>
            </div>
          )}

          {step === 2 && (
            <div className="space-y-6">
              <div className="flex items-center gap-3 mb-2">
                <button onClick={() => setStep(1)} className="text-stone-400 hover:text-stone-900"><i className="fa-solid fa-arrow-left"></i></button>
                <h3 className="font-bold text-stone-800 text-lg">Enter {method} Details</h3>
              </div>
              <input type="text" placeholder={method === 'UPI' ? "example@upi" : "Card Number"} className="w-full bg-stone-50 border border-stone-100 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-emerald-500" />
              <button 
                onClick={handlePay}
                className="w-full bg-emerald-600 text-white font-black py-4 rounded-2xl hover:bg-emerald-700 shadow-xl shadow-emerald-100"
              >
                Complete Payment
              </button>
            </div>
          )}

          {step === 3 && (
            <div className="text-center py-10">
              <div className="relative w-24 h-24 mx-auto mb-6">
                <div className="absolute inset-0 border-4 border-stone-100 rounded-full"></div>
                <div className="absolute inset-0 border-4 border-emerald-500 rounded-full border-t-transparent animate-spin"></div>
              </div>
              <h3 className="text-xl font-bold text-stone-800 mb-2">Processing...</h3>
              <p className="text-stone-500">Talking to your bank securely. Do not refresh.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

