            </div>
            <button 
              onClick={() => addToCart(product)}
              className="mt-auto w-full bg-stone-900 text-white font-black py-3 rounded-2xl text-xs hover:bg-emerald-600 transition-all shadow-xl shadow-stone-100"
            >
              Add to Bag
            </button>
          </div>
        </div>
      ))}
    </div>
  );

  const renderContent = () => {
    switch (activeTab) {
      case 'explore':
        const vegetables = PRODUCTS.filter(p => p.category === 'Vegetables');
        const fruits = PRODUCTS.filter(p => p.category === 'Fruits');

        return (
          <div className="space-y-12 pb-24 md:pb-12">
