                </div>
                <p className="text-emerald-600 font-bold text-xl mb-1">Direct from India's Farmers.</p>
                <div className="flex items-center gap-2 text-stone-500 font-medium h-6">
                  {loadingMarkets ? (
                    <span className="flex items-center gap-2 text-xs"><i className="fa-solid fa-spinner animate-spin"></i> Checking nearby Mandis...</span>
                  ) : userLocation ? (
                    <><i className="fa-solid fa-location-crosshairs text-emerald-500"></i> Mandis found in your area.</>
                  ) : (
                    <>Buy fresh directly from local producers.</>
                  )}
                </div>
              </div>
              <div className="flex gap-4">
