                    <p className="text-stone-400 font-bold">Your bag is empty. Start shopping!</p>
                  </div>
                ) : (
                  <>
                    <div className="space-y-3 mb-8 max-h-72 overflow-y-auto pr-4 scrollbar-thin scrollbar-thumb-emerald-200">
                      {cart.map((item, idx) => (
                        <div key={idx} className="flex justify-between items-center py-3 border-b border-stone-100 last:border-0">
                          <span className="text-stone-700 font-bold">{item.name}</span>
                          <span className="font-black text-stone-900">₹{item.price}</span>
                        </div>
                      ))}
                    </div>
                    <div className="flex justify-between items-center mb-8 bg-emerald-50 p-6 rounded-3xl border border-emerald-100">
                      <span className="font-black text-stone-700 text-xl">Total Payable</span>
                      <span className="font-black text-emerald-700 text-3xl">₹{cartTotal}</span>
                    </div>
                    <button 
                      onClick={() => setShowPayment(true)}
                      className="w-full bg-emerald-600 text-white font-black py-5 rounded-2xl hover:bg-emerald-700 transition-all shadow-2xl shadow-emerald-100 text-lg flex items-center justify-center gap-3"
                    >
                      Pay ₹{cartTotal} & Confirm
