          <div className="space-y-4">
            {history.map(item => (
              <div key={item.id} className="bg-stone-50 p-6 rounded-3xl border border-stone-100 group hover:bg-emerald-50 transition-colors">
                <div className="flex justify-between items-start mb-4">
                  <div>
                    <p className="text-xs font-black text-stone-400 uppercase tracking-widest mb-1">{item.date}</p>
                    <p className="text-stone-900 font-black text-lg">Order #{item.id.slice(-6)}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-2xl font-black text-emerald-700">₹{item.total}</p>
                    <span className="inline-block bg-emerald-100 text-emerald-700 text-[10px] font-black px-2 py-0.5 rounded uppercase">Confirmed</span>
                  </div>
                </div>
                <div className="bg-white/50 rounded-2xl p-4 border border-stone-100">
                   <p className="text-xs font-black text-stone-400 uppercase tracking-widest mb-3">Items Purchased</p>
                   <div className="flex flex-wrap gap-2">
                     {item.items.map((it, idx) => (
                       <span key={idx} className="bg-stone-100 text-stone-700 px-3 py-1.5 rounded-xl text-xs font-bold border border-stone-200">
                         {it}
                       </span>
                     ))}
                   </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

