const App: React.FC = () => {
  // Load persistent states from localStorage on initialization
  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('hh_session') === 'true');
  const [userName, setUserName] = useState(() => localStorage.getItem('hh_username') || '');
  const [activeTab, setActiveTab] = useState('explore');
  const [loadingMarkets, setLoadingMarkets] = useState(false);
  const [cart, setCart] = useState<Array<{ id: string; name: string; price: number }>>([]);
  const [showCart, setShowCart] = useState(false);
  const [showRegisterModal, setShowRegisterModal] = useState(false);
  const [showPayment, setShowPayment] = useState(false);
  const [showHistory, setShowHistory] = useState(false);

  // Persist allFarmers
  const [allFarmers, setAllFarmers] = useState<Farmer[]>(() => {
    const saved = localStorage.getItem('hh_farmers');
    return saved ? JSON.parse(saved) : FARMERS;
  });

  const [markets, setMarkets] = useState<Market[]>(MARKETS);
  const [userLocation, setUserLocation] = useState<GeolocationPosition | null>(null);

  // Persist purchase history
  const [purchaseHistory, setPurchaseHistory] = useState<PurchaseHistoryItem[]>(() => {
    const saved = localStorage.getItem('hh_history');
    return saved ? JSON.parse(saved) : [];
  });

  // Persist user stats
  const [userStats, setUserStats] = useState<UserStats>(() => {
    const saved = localStorage.getItem('hh_stats');
    return saved ? JSON.parse(saved) : {
      marketsVisited: 0,
      co2SavedKg: 0,
      localEconomySupport: 0,
      badgesEarned: 0
    };
  });

  // Save states whenever they change
  useEffect(() => {
    localStorage.setItem('hh_farmers', JSON.stringify(allFarmers));
  }, [allFarmers]);

  useEffect(() => {
    localStorage.setItem('hh_history', JSON.stringify(purchaseHistory));
  }, [purchaseHistory]);

  useEffect(() => {
    localStorage.setItem('hh_stats', JSON.stringify(userStats));
  }, [userStats]);

  useEffect(() => {
    localStorage.setItem('hh_session', String(isLoggedIn));
    localStorage.setItem('hh_username', userName);
  }, [isLoggedIn, userName]);

  useEffect(() => {
    if (!isLoggedIn) return;
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        async (position) => {
          setUserLocation(position);
          setLoadingMarkets(true);
          const nearby = await getNearbyMarkets(position.coords.latitude, position.coords.longitude);
          if (nearby && Array.isArray(nearby)) setMarkets(nearby);
          setLoadingMarkets(false);
          setUserStats(prev => ({ ...prev, marketsVisited: nearby?.length || prev.marketsVisited }));
        },
        () => setLoadingMarkets(false)
      );
    }
  }, [isLoggedIn]);

  const addToCart = (product: any) => {
    setCart(prev => [...prev, { id: product.id, name: product.name, price: product.price }]);
    const toast = document.createElement('div');
    toast.className = 'fixed bottom-10 right-10 bg-emerald-600 text-white px-6 py-3 rounded-full text-sm font-bold shadow-2xl z-[1000] animate-bounce';
    toast.innerText = `Added ${product.name} to Bag! 🛍️`;
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 2000);
  };

  const onPaymentSuccess = () => {
    const total = cartTotal;
    const items = cart.map(c => c.name);

    setUserStats(prev => ({
      ...prev,
      localEconomySupport: prev.localEconomySupport + total,
      co2SavedKg: prev.co2SavedKg + (total / 100 * 0.4) 
    }));

    const newRecord: PurchaseHistoryItem = {
      id: 'ord_' + Math.floor(Math.random() * 1000000),
      date: new Date().toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }),
      items: items,
      total: total
    };
    setPurchaseHistory(prev => [newRecord, ...prev]);

    setShowPayment(false);
    setCart([]);
    setShowCart(false);
    alert(`Success! ₹${total} paid to our Farmer partners. Thank you for buying local!`);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setUserName('');
    localStorage.removeItem('hh_session');
    localStorage.removeItem('hh_username');
  };

  const cartTotal = cart.reduce((sum, item) => sum + item.price, 0);

  const renderProductGrid = (products: Product[]) => (
    <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-6">
      {products.map(product => (
        <div key={product.id} className="bg-white rounded-[2rem] border border-stone-200 overflow-hidden group hover:shadow-xl transition-all flex flex-col">
          <div className="h-48 overflow-hidden relative">
            <img src={product.image} alt={product.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
            <div className="absolute inset-0 bg-black/5 group-hover:bg-transparent transition-colors"></div>
          </div>
          <div className="p-5 flex-1 flex flex-col">
            <h4 className="font-black text-stone-800 mb-1 text-lg">{product.name}</h4>
            <div className="flex justify-between items-center mb-4">
              <span className="text-emerald-600 font-black text-xl">₹{product.price}</span>
              <span className="text-xs text-stone-400 font-bold uppercase tracking-wider">per {product.unit}</span>
            </div>
            <button 
              onClick={() => addToCart(product)}
              className="mt-auto w-full bg-stone-900 text-white font-black py-3 rounded-2xl text-xs hover:bg-emerald-600 transition-all shadow-xl shadow-stone-100"
            >
              Add to Bag
            </button>
          </div>
        </div>
      ))}
    </div>
  );

  const renderContent = () => {
    switch (activeTab) {
      case 'explore':
        const vegetables = PRODUCTS.filter(p => p.category === 'Vegetables');
        const fruits = PRODUCTS.filter(p => p.category === 'Fruits');
        return (
          <div className="space-y-12 pb-24 md:pb-12">
            <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
              <div className="flex-1">
                <h2 className="text-4xl font-extrabold text-stone-900 leading-tight tracking-tight mb-2">Welcome, {userName}</h2>
                <p className="text-emerald-600 font-bold text-xl mb-1">Direct from India's Farmers.</p>
                <div className="flex items-center gap-2 text-stone-500 font-medium h-6">
                  {loadingMarkets ? (
                    <span className="flex items-center gap-2 text-xs"><i className="fa-solid fa-spinner animate-spin"></i> Checking nearby Mandis...</span>
                  ) : userLocation ? (
                    <><i className="fa-solid fa-location-crosshairs text-emerald-500"></i> Mandis found in your area.</>
                  ) : (
                    <>Buy fresh directly from local producers.</>
                  )}
                </div>
              </div>
              <div className="flex gap-4">
                <button onClick={() => setShowHistory(true)} className="bg-white border border-stone-200 p-4 rounded-2xl shadow-sm hover:shadow-md transition-all text-stone-600 flex items-center gap-2 font-bold group">
                  <i className="fa-solid fa-clock-rotate-left group-hover:rotate-12 transition-transform"></i>
                  <span className="hidden md:inline">Purchase History</span>
                </button>
                <button 
                  onClick={() => setShowCart(!showCart)}
                  className={`relative p-4 rounded-2xl shadow-sm hover:shadow-md transition-all group border-2 ${showCart ? 'bg-emerald-600 border-emerald-600 text-white' : 'bg-white border-stone-100 text-emerald-600'}`}
                >
                  <i className="fa-solid fa-bag-shopping text-2xl"></i>
                  {cart.length > 0 && (
                    <span className="absolute -top-3 -right-3 bg-red-500 text-white text-[11px] font-black w-7 h-7 flex items-center justify-center rounded-full border-2 border-white shadow-lg">
                      {cart.length}
                    </span>
                  )}
                  <span className={`ml-2 font-black hidden md:inline ${showCart ? 'text-white' : 'text-stone-700'}`}>₹{cartTotal}</span>
                </button>
              </div>
            </header>
            {showCart && (
              <div className="bg-white rounded-[2.5rem] p-8 border border-emerald-100 shadow-2xl animate-in fade-in slide-in-from-top-4 duration-300">
                <div className="flex justify-between items-center mb-6">
                  <h3 className="text-2xl font-black text-stone-800">Your Fresh Bag</h3>
                  <button onClick={() => setCart([])} className="text-xs text-red-500 font-black uppercase tracking-widest hover:underline">Clear Items</button>
                </div>
                {cart.length === 0 ? (
                  <div className="text-center py-10 bg-stone-50 rounded-3xl border border-dashed border-stone-200">
                    <i className="fa-solid fa-cart-shopping text-4xl text-stone-200 mb-3 block"></i>
                    <p className="text-stone-400 font-bold">Your bag is empty. Start shopping!</p>
                  </div>
                ) : (
                  <>
                    <div className="space-y-3 mb-8 max-h-72 overflow-y-auto pr-4 scrollbar-thin scrollbar-thumb-emerald-200">
                      {cart.map((item, idx) => (
                        <div key={idx} className="flex justify-between items-center py-3 border-b border-stone-100 last:border-0">
                          <span className="text-stone-700 font-bold">{item.name}</span>
                          <span className="font-black text-stone-900">₹{item.price}</span>
                        </div>
                      ))}
                    </div>
                    <div className="flex justify-between items-center mb-8 bg-emerald-50 p-6 rounded-3xl border border-emerald-100">
                      <span className="font-black text-stone-700 text-xl">Total Payable</span>
                      <span className="font-black text-emerald-700 text-3xl">₹{cartTotal}</span>
                    </div>
                    <button onClick={() => setShowPayment(true)} className="w-full bg-emerald-600 text-white font-black py-5 rounded-2xl hover:bg-emerald-700 transition-all shadow-2xl shadow-emerald-100 text-lg flex items-center justify-center gap-3">Pay ₹{cartTotal} & Confirm</button>
                  </>
                )}
              </div>
            )}
            <section>
              <h3 className="text-2xl font-black text-stone-800 mb-8 flex items-center gap-3"><div className="bg-orange-100 w-10 h-10 rounded-xl flex items-center justify-center"><i className="fa-solid fa-carrot text-orange-600"></i></div>Pure Vegetables</h3>
              {renderProductGrid(vegetables)}
            </section>
            <section>
              <h3 className="text-2xl font-black text-stone-800 mb-8 flex items-center gap-3"><div className="bg-red-100 w-10 h-10 rounded-xl flex items-center justify-center"><i className="fa-solid fa-apple-whole text-red-600"></i></div>Fresh Seasonal Fruits</h3>
              {renderProductGrid(fruits)}
            </section>
          </div>
        );
      case 'markets':
        return (
          <div className="space-y-8 pb-24 md:pb-12">
            <h2 className="text-3xl font-black text-stone-900 mb-2">Nearby Local Mandi</h2>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              {markets.map(market => <MarketCard key={market.id} market={market} />)}
            </div>
          </div>
        );
      case 'farmers':
        return (
          <div className="space-y-8 pb-24 md:pb-12">
            <h2 className="text-3xl font-black text-stone-900 mb-2">Our Kisan Community</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {allFarmers.map(farmer => <FarmerCard key={farmer.id} farmer={farmer} />)}
              <div 
                onClick={() => setShowRegisterModal(true)}
                className="bg-emerald-50 rounded-[2.5rem] p-8 border-2 border-dashed border-emerald-200 flex flex-col items-center justify-center text-center group cursor-pointer hover:bg-emerald-100 transition-colors h-full min-h-[350px]"
              >
                <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mb-4 shadow-sm group-hover:scale-110 transition-transform">
                  <i className="fa-solid fa-plus text-emerald-600 text-2xl"></i>
                </div>
                <h3 className="text-xl font-black text-emerald-900">Are you a Farmer?</h3>
                <p className="text-emerald-700 font-medium mb-6">Create your profile and start selling directly.</p>
                <button className="bg-emerald-700 text-white font-bold py-3 px-8 rounded-xl shadow-lg">Join Community</button>
              </div>
            </div>
          </div>
        );
      case 'kitchen': return <AIKitchen />;
      case 'stats': return <ImpactStats stats={userStats} />;
      default: return null;
    }
  };

  if (!isLoggedIn) {
    return <Auth onLogin={(name) => { setUserName(name); setIsLoggedIn(true); }} />;
  }

  return (
    <div className="min-h-screen md:pl-64">
      <Navigation 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onLogout={handleLogout}
      />
      <main className="max-w-7xl mx-auto p-6 md:p-12">
        {renderContent()}
      </main>
      {showRegisterModal && (
        <FarmerRegistration 
          onClose={() => setShowRegisterModal(false)} 
          onAdd={(newFarmer) => setAllFarmers(prev => [newFarmer, ...prev])} 
        />
      )}
      {showPayment && (
        <PaymentGateway total={cartTotal} onCancel={() => setShowPayment(false)} onSuccess={onPaymentSuccess} />
      )}
      {showHistory && (
        <HistoryModal history={purchaseHistory} onClose={() => setShowHistory(false)} />
      )}
    </div>
  );
};

