import React, { useState, useEffect } from 'react';
import Navigation from './components/Navigation';
import MarketCard from './components/MarketCard';
import FarmerCard from './components/FarmerCard';
import ImpactStats from './components/ImpactStats';
import AIKitchen from './components/AIKitchen';
import { MARKETS, FARMERS, PRODUCTS } from './constants';
import { getNearbyMarkets } from './services/geminiService';
import { Farmer, Market, UserStats, PurchaseHistoryItem, Product } from './types';

// --- AUTH COMPONENTS ---

const Auth: React.FC<{ onLogin: (name: string) => void }> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [name, setName] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    const storedUsers = JSON.parse(localStorage.getItem('hh_users') || '[]');

    if (isLogin) {
      const user = storedUsers.find((u: any) => u.name === name && u.password === password);
      if (user) {
        onLogin(user.name);
      } else {
        setError('Wrong username or password! Please try again.');
      }
    } else {
      if (storedUsers.some((u: any) => u.name === name)) {
        setError('User already exists! Try a different name.');
      } else {
        storedUsers.push({ name, password });
        localStorage.setItem('hh_users', JSON.stringify(storedUsers));
        onLogin(name);
      }
    }
  };

  return (
    <div className="fixed inset-0 bg-emerald-900 flex items-center justify-center p-6 z-[999]">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] p-10 shadow-2xl animate-in fade-in zoom-in duration-500">
        <div className="flex flex-col items-center mb-10">
          <div className="bg-emerald-600 p-4 rounded-3xl mb-4 shadow-lg">
            <i className="fa-solid fa-leaf text-3xl text-white"></i>
          </div>
          <h1 className="text-3xl font-black text-stone-900 tracking-tight">HarvestHub</h1>
          <p className="text-stone-500 font-medium text-center">Support your local Farmers</p>
        </div>

        <form onSubmit={handleAuth} className="space-y-6">
          <div>
            <label className="block text-xs font-black text-stone-400 uppercase tracking-widest mb-2">User Name</label>
            <input 
              type="text" required placeholder="Enter your name" 
              className="w-full bg-stone-50 border border-stone-200 rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-emerald-500"
              value={name} onChange={(e) => setName(e.target.value)}
            />
          </div>
          <div>
            <label className="block text-xs font-black text-stone-400 uppercase tracking-widest mb-2">Password</label>
            <input 
              type="password" required placeholder="Create/Enter password" 
              className="w-full bg-stone-50 border border-stone-200 rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-emerald-500"
              value={password} onChange={(e) => setPassword(e.target.value)}
            />
          </div>
          {error && <p className="text-red-500 text-xs font-bold text-center">{error}</p>}
          <button type="submit" className="w-full bg-emerald-600 text-white font-black py-4 rounded-2xl hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-100">
            {isLogin ? 'Login' : 'Join HarvestHub'}
          </button>
        </form>

        <div className="mt-8 pt-8 border-t border-stone-100 text-center">
          <button onClick={() => { setIsLogin(!isLogin); setError(''); }} className="text-emerald-600 font-black text-sm hover:underline">
            {isLogin ? "Don't have an account? Sign Up" : "Already have an account? Login"}
          </button>
        </div>
      </div>
    </div>
  );
};

// --- LOCATION ONBOARDING ---

const LocationPrompt: React.FC<{ onGrant: (pos: GeolocationPosition) => void; onSkip: () => void }> = ({ onGrant, onSkip }) => {
  const [requesting, setRequesting] = useState(false);

  const handleRequest = () => {
    setRequesting(true);
    navigator.geolocation.getCurrentPosition(
      (pos) => { onGrant(pos); },
      (err) => { 
        console.error(err);
        setRequesting(false);
        alert("Location access denied. You can still browse, but we won't be able to find your local mandis.");
        onSkip();
      },
      { timeout: 10000 }
    );
  };

  return (
    <div className="fixed inset-0 bg-stone-900/60 backdrop-blur-md z-[800] flex items-center justify-center p-6">
      <div className="bg-white w-full max-w-lg rounded-[3rem] p-12 text-center shadow-2xl">
        <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center mx-auto mb-8 animate-bounce">
          <i className="fa-solid fa-location-dot text-4xl text-emerald-600"></i>
        </div>
        <h2 className="text-3xl font-black text-stone-900 mb-4">Find Your Local Mandis</h2>
        <p className="text-stone-500 font-medium mb-10 leading-relaxed">
          Allow location access to discover fresh products from farmers right in your neighborhood. Help us support your local kisan!
        </p>
        <div className="space-y-4">
          <button 
            onClick={handleRequest}
            disabled={requesting}
            className="w-full bg-emerald-600 text-white font-black py-5 rounded-3xl hover:bg-emerald-700 shadow-xl shadow-emerald-100 transition-all text-lg flex items-center justify-center gap-3"
          >
            {requesting ? <i className="fa-solid fa-spinner animate-spin"></i> : <i className="fa-solid fa-compass"></i>}
            Enable Location
          </button>
          <button onClick={onSkip} className="text-stone-400 font-bold hover:text-stone-600">Maybe Later</button>
        </div>
      </div>
    </div>
  );
};

// --- APP COMPONENT ---

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('hh_session') === 'true');
  const [userName, setUserName] = useState(() => localStorage.getItem('hh_username') || '');
  const [activeTab, setActiveTab] = useState('explore');
  const [loadingMarkets, setLoadingMarkets] = useState(false);
  const [cart, setCart] = useState<Array<{ id: string; name: string; price: number }>>([]);
  const [showCart, setShowCart] = useState(false);
  const [showRegisterModal, setShowRegisterModal] = useState(false);
  const [showPayment, setShowPayment] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [showLocationPrompt, setShowLocationPrompt] = useState(false);

  const [allFarmers, setAllFarmers] = useState<Farmer[]>(() => {
    const saved = localStorage.getItem('hh_farmers');
    return saved ? JSON.parse(saved) : FARMERS;
  });

  const [markets, setMarkets] = useState<Market[]>(() => {
    const saved = localStorage.getItem('hh_markets');
    return saved ? JSON.parse(saved) : MARKETS;
  });

  const [userLocation, setUserLocation] = useState<GeolocationPosition | null>(null);

  const [purchaseHistory, setPurchaseHistory] = useState<PurchaseHistoryItem[]>(() => {
    const saved = localStorage.getItem('hh_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [userStats, setUserStats] = useState<UserStats>(() => {
    const saved = localStorage.getItem('hh_stats');
    return saved ? JSON.parse(saved) : {
      marketsVisited: 0,
      co2SavedKg: 0,
      localEconomySupport: 0,
      badgesEarned: 0
    };
  });

  // Persist data on change
  useEffect(() => { localStorage.setItem('hh_farmers', JSON.stringify(allFarmers)); }, [allFarmers]);
  useEffect(() => { localStorage.setItem('hh_history', JSON.stringify(purchaseHistory)); }, [purchaseHistory]);
  useEffect(() => { localStorage.setItem('hh_stats', JSON.stringify(userStats)); }, [userStats]);
  useEffect(() => { localStorage.setItem('hh_markets', JSON.stringify(markets)); }, [markets]);
  useEffect(() => {
    localStorage.setItem('hh_session', String(isLoggedIn));
    localStorage.setItem('hh_username', userName);
    if (isLoggedIn && !userLocation && markets === MARKETS) {
       setShowLocationPrompt(true);
    }
  }, [isLoggedIn, userName]);

  const fetchNearbyMarkets = async (pos: GeolocationPosition) => {
    setUserLocation(pos);
    setShowLocationPrompt(false);
    setLoadingMarkets(true);
    try {
      const nearby = await getNearbyMarkets(pos.coords.latitude, pos.coords.longitude);
      if (nearby && Array.isArray(nearby)) {
        setMarkets(nearby);
        setUserStats(prev => ({ ...prev, marketsVisited: nearby.length }));
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingMarkets(false);
    }
  };

  const addToCart = (product: any) => {
    setCart(prev => [...prev, { id: product.id, name: product.name, price: product.price }]);
    const toast = document.createElement('div');
    toast.className = 'fixed bottom-10 right-10 bg-emerald-600 text-white px-6 py-3 rounded-full text-sm font-bold shadow-2xl z-[1000] animate-bounce';
    toast.innerText = `Added ${product.name} to Bag! 🛍️`;
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 2000);
  };

  const onPaymentSuccess = () => {
    const total = cartTotal;
    const items = cart.map(c => c.name);
    setUserStats(prev => ({
      ...prev,
      localEconomySupport: prev.localEconomySupport + total,
      co2SavedKg: prev.co2SavedKg + (total / 100 * 0.4) 
    }));
    const newRecord: PurchaseHistoryItem = {
      id: 'ord_' + Math.floor(Math.random() * 1000000),
      date: new Date().toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }),
      items: items,
      total: total
    };
    setPurchaseHistory(prev => [newRecord, ...prev]);
    setShowPayment(false);
    setCart([]);
    setShowCart(false);
    alert(`Success! ₹${total} paid to our Farmer partners. Thank you for buying local!`);
  };

  const cartTotal = cart.reduce((sum, item) => sum + item.price, 0);

  const renderProductGrid = (products: Product[]) => (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
      {products.map(product => (
        <div key={product.id} className="bg-white rounded-[2rem] border border-stone-100 overflow-hidden group hover:shadow-xl transition-all flex flex-col">
          <div className="h-48 overflow-hidden relative">
            <img src={product.image} alt={product.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
            <div className="absolute inset-0 bg-black/5 group-hover:bg-transparent transition-colors"></div>
          </div>
          <div className="p-6 flex-1 flex flex-col">
            <h4 className="font-black text-stone-800 mb-1 text-lg">{product.name}</h4>
            <div className="flex justify-between items-center mb-6">
              <span className="text-emerald-700 font-black text-xl">₹{product.price}</span>
              <span className="text-xs text-stone-400 font-bold uppercase tracking-wider">/{product.unit}</span>
            </div>
            <button 
              onClick={() => addToCart(product)}
              className="mt-auto w-full bg-stone-900 text-white font-black py-4 rounded-2xl text-sm hover:bg-emerald-600 transition-all shadow-xl shadow-stone-100"
            >
              Add to Bag
            </button>
          </div>
        </div>
      ))}
    </div>
  );

  const renderContent = () => {
    switch (activeTab) {
      case 'explore':
        const vegetables = PRODUCTS.filter(p => p.category === 'Vegetables');
        const fruits = PRODUCTS.filter(p => p.category === 'Fruits');
