          <div className="space-y-12 pb-24 md:pb-12">
            <header className="flex flex-col md:flex-row md:items-end justify-between gap-6">
              <div className="flex-1">
                <h2 className="text-4xl font-extrabold text-stone-900 tracking-tight mb-2">Namaste, {userName}</h2>
                <div className="flex items-center gap-3">
                  <p className="text-emerald-600 font-bold text-xl">Supporting local Indian Farmers.</p>
                  {loadingMarkets && <i className="fa-solid fa-spinner animate-spin text-emerald-500"></i>}
                </div>
                {userLocation && (
                  <p className="text-stone-400 text-xs mt-2 font-bold flex items-center gap-2">
                    <i className="fa-solid fa-location-arrow text-emerald-500"></i> Localizing for your current area...
                  </p>
                )}
              </div>
              <div className="flex gap-4">
                <button 
                  onClick={() => setShowCart(!showCart)}
                  className={`relative p-5 rounded-3xl shadow-lg transition-all border-2 flex items-center gap-3 ${showCart ? 'bg-emerald-600 border-emerald-600 text-white' : 'bg-white border-stone-100 text-emerald-600'}`}
                >
                  <i className="fa-solid fa-bag-shopping text-2xl"></i>
                  {cart.length > 0 && <span className="absolute -top-3 -right-3 bg-red-500 text-white text-[11px] font-black w-8 h-8 flex items-center justify-center rounded-full border-4 border-white shadow-xl">{cart.length}</span>}
                  <span className={`font-black hidden md:inline ${showCart ? 'text-white' : 'text-stone-700'}`}>₹{cartTotal}</span>
                </button>
              </div>
            </header>

            {showCart && (
              <div className="bg-white rounded-[3rem] p-10 border border-emerald-100 shadow-2xl animate-in fade-in slide-in-from-top-6 duration-300">
                <div className="flex justify-between items-center mb-8">
                  <h3 className="text-2xl font-black text-stone-800">My Fresh Harvest</h3>
                  <button onClick={() => setCart([])} className="text-xs text-red-500 font-black uppercase tracking-widest hover:underline">Clear Items</button>
                </div>
                {cart.length === 0 ? (
                  <div className="text-center py-10 bg-stone-50 rounded-[2rem] border-2 border-dashed border-stone-200">
                    <i className="fa-solid fa-cart-arrow-down text-4xl text-stone-200 mb-4 block"></i>
                    <p className="text-stone-400 font-bold">Your shopping bag is empty.</p>
                  </div>
                ) : (
                  <>
                    <div className="space-y-4 mb-10 max-h-72 overflow-y-auto pr-4 scrollbar-hide">
                      {cart.map((item, idx) => (
                        <div key={idx} className="flex justify-between items-center py-3 border-b border-stone-50 last:border-0">
                          <span className="text-stone-700 font-bold">{item.name}</span>
                          <span className="font-black text-stone-900">₹{item.price}</span>
                        </div>
                      ))}
                    </div>
                    <div className="flex justify-between items-center mb-10 bg-emerald-50 p-8 rounded-[2.5rem] border border-emerald-100">
                      <span className="font-black text-stone-700 text-xl">Total To Pay</span>
                      <span className="font-black text-emerald-700 text-4xl">₹{cartTotal}</span>
                    </div>
                    <button onClick={() => setShowPayment(true)} className="w-full bg-emerald-600 text-white font-black py-6 rounded-3xl hover:bg-emerald-700 transition-all shadow-2xl shadow-emerald-100 text-xl">Confirm Order</button>
                  </>
                )}
              </div>
            )}

            {markets !== MARKETS && (
              <section className="bg-gradient-to-br from-emerald-50 to-white p-8 rounded-[3rem] border border-emerald-100 shadow-sm animate-in fade-in duration-1000">
                <h3 className="text-2xl font-black text-stone-800 mb-6 flex items-center gap-3">
                  <div className="bg-emerald-200 w-10 h-10 rounded-xl flex items-center justify-center">
                    <i className="fa-solid fa-map-location-dot text-emerald-700"></i>
                  </div>
                  Mandis Found In Your Region
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {markets.slice(0, 3).map(m => (
                    <div key={m.id} className="bg-white p-6 rounded-3xl shadow-sm border border-stone-100 hover:scale-[1.02] transition-transform">
                       <h4 className="font-black text-stone-800">{m.name}</h4>
                       <p className="text-xs text-stone-400 mt-1 mb-4 flex items-center gap-1"><i className="fa-solid fa-location-dot"></i> {m.distance} away</p>
                       <p className="text-[10px] font-black uppercase text-emerald-600 bg-emerald-50 px-2 py-1 rounded inline-block">Active: {m.hours}</p>
                    </div>
                  ))}
                </div>
              </section>
            )}

            <section>
              <h3 className="text-2xl font-black text-stone-800 mb-8 flex items-center gap-3">
                <div className="bg-orange-100 w-10 h-10 rounded-xl flex items-center justify-center"><i className="fa-solid fa-carrot text-orange-600"></i></div>
                Pure Vegetables
              </h3>
              {renderProductGrid(vegetables)}
