import { GoogleGenAI, Type } from "@google/genai";

// Always use named parameter for apiKey and direct process.env.API_KEY access
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getRecipeFromIngredients = async (ingredients: string[]) => {
  const prompt = `Generate a simple and tasty Indian style recipe using these local market ingredients: ${ingredients.join(', ')}. Use simple English. Include an Indian title, cooking time, and easy steps.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            prepTime: { type: Type.STRING },
            difficulty: { type: Type.STRING },
            ingredients: { 
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            instructions: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            nutritionTip: { type: Type.STRING }
          },
          required: ['title', 'prepTime', 'difficulty', 'ingredients', 'instructions']
        }
      }
    });

    return JSON.parse(response.text || '{}');
  } catch (error) {
    console.error("Error generating recipe:", error);
    return null;
  }
};

export const getNearbyMarkets = async (lat: number, lng: number) => {
  const prompt = `Act as a local guide. I am located at coordinates Latitude: ${lat}, Longitude: ${lng}. 
  Find or generate 3-4 highly realistic and specific local Indian farmer market (Sabzi Mandi) names, exact addresses, and operating hours for this specific area. 
  Ensure the names reflect the local culture or common naming conventions of that region. 
  Return the data as a JSON list.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              name: { type: Type.STRING },
              address: { type: Type.STRING },
              distance: { type: Type.STRING },
              days: { 
                type: Type.ARRAY, 
                items: { type: Type.STRING } 
              },
              hours: { type: Type.STRING },
              vendorsCount: { type: Type.NUMBER }
            },
            required: ['id', 'name', 'address', 'distance', 'days', 'hours', 'vendorsCount']
          }
        }
      }
    });

    return JSON.parse(response.text || '[]');
  } catch (error) {
    console.error("Error fetching local markets:", error);
    return null;
  }
};

export const getSeasonalAdvice = async (month: string) => {
  const prompt = `What are the best 3 things to buy at an Indian local market (Mandi) in ${month}? Tell me the items and why they are good now in simple English. Also give 1 simple tip to save nature while shopping.`;

