          onClick={onLogout}
          className="flex flex-col md:flex-row items-center gap-1 md:gap-4 px-3 py-2 md:px-6 md:py-3 rounded-xl transition-all duration-200 text-stone-400 hover:text-red-600 hover:bg-red-50"
