import { Farmer, PurchaseHistoryItem, UserStats } from '../types';
import { FARMERS } from '../constants';

/**
 * Backend Simulation Service
 * In a real-world scenario, these would be calls to a Node.js/Python server with a real database.
 * For this VS Code / Static hosting environment, we use localStorage as the "Persistent Database".
 */

const STORAGE_KEYS = {
  USERS: 'hh_db_users',
  FARMERS: 'hh_db_farmers',
  ORDERS: 'hh_db_orders',
  STATS: 'hh_db_stats',
  SESSION: 'hh_db_session'
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const db = {
  // --- AUTH / USER MANAGEMENT ---
  async getUsers() {
    const data = localStorage.getItem(STORAGE_KEYS.USERS);
    return data ? JSON.parse(data) : [];
  },

  async registerUser(name: string, password: string) {
    await delay(500); // Simulate network latency
    const users = await this.getUsers();
    if (users.find((u: any) => u.name === name)) {
      throw new Error('User already exists');
    }
    const newUser = { name, password, createdAt: new Date().toISOString() };
    users.push(newUser);
    localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify(users));
    return newUser;
  },

  async loginUser(name: string, password: string) {
    await delay(500);
    const users = await this.getUsers();
    const user = users.find((u: any) => u.name === name && u.password === password);
    if (!user) throw new Error('Invalid credentials');
    localStorage.setItem(STORAGE_KEYS.SESSION, JSON.stringify({ name, loginTime: Date.now() }));
    return user;
  },

  async getSession() {
    const session = localStorage.getItem(STORAGE_KEYS.SESSION);
    return session ? JSON.parse(session) : null;
  },

  async logout() {
    localStorage.removeItem(STORAGE_KEYS.SESSION);
  },

  // --- FARMER PERSISTENCE ---
  async getFarmers(): Promise<Farmer[]> {
    const data = localStorage.getItem(STORAGE_KEYS.FARMERS);
    if (!data) {
      // Initialize with default farmers if DB is empty
      localStorage.setItem(STORAGE_KEYS.FARMERS, JSON.stringify(FARMERS));
      return FARMERS;
    }
    return JSON.parse(data);
  },

  async addFarmer(farmer: Farmer) {
    await delay(300);
    const farmers = await this.getFarmers();
    const updated = [farmer, ...farmers];
    localStorage.setItem(STORAGE_KEYS.FARMERS, JSON.stringify(updated));
    return updated;
  },

  // --- PURCHASE HISTORY ---
  async getPurchaseHistory(username: string): Promise<PurchaseHistoryItem[]> {
    const data = localStorage.getItem(`${STORAGE_KEYS.ORDERS}_${username}`);
    return data ? JSON.parse(data) : [];
  },

  async saveOrder(username: string, order: PurchaseHistoryItem) {
    await delay(800);
    const history = await this.getPurchaseHistory(username);
    const updated = [order, ...history];
    localStorage.setItem(`${STORAGE_KEYS.ORDERS}_${username}`, JSON.stringify(updated));
    return updated;
  },

  // --- USER STATS ---
  async getUserStats(username: string): Promise<UserStats> {
    const data = localStorage.getItem(`${STORAGE_KEYS.STATS}_${username}`);
    return data ? JSON.parse(data) : {
      marketsVisited: 0,
      co2SavedKg: 0,
      localEconomySupport: 0,
      badgesEarned: 0
    };
  },

  async saveUserStats(username: string, stats: UserStats) {
    localStorage.setItem(`${STORAGE_KEYS.STATS}_${username}`, JSON.stringify(stats));
  }
};

