          <i className="fa-solid fa-xmark text-xl"></i>
        </button>
        <h2 className="text-3xl font-black text-stone-900 mb-8">My Purchase History</h2>
        {history.length === 0 ? (
          <div className="text-center py-16">
            <i className="fa-solid fa-receipt text-6xl text-stone-100 mb-4 block"></i>
            <p className="text-stone-400 font-bold">No past orders yet.</p>
          </div>
        ) : (
          <div className="space-y-4">
            {history.map(item => (
              <div key={item.id} className="bg-stone-50 p-6 rounded-[2rem] border border-stone-100 group hover:border-emerald-200 transition-colors">
                <div className="flex justify-between items-start mb-4">
                  <div>
                    <p className="text-[10px] font-black text-stone-400 uppercase tracking-[0.2em] mb-1">{item.date}</p>
                    <p className="font-black text-stone-800">Order #{item.id}</p>
                  </div>
                  <span className="bg-emerald-100 text-emerald-700 px-4 py-1.5 rounded-xl text-xs font-black border border-emerald-200">₹{item.total}</span>
                </div>
                <div className="flex flex-wrap gap-2">
                  {item.items.map((it, idx) => (
                    <span key={idx} className="bg-white text-stone-600 px-3 py-1 rounded-lg text-[10px] font-bold border border-stone-200">{it}</span>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

// --- APP COMPONENT ---

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [userName, setUserName] = useState('');
  const [activeTab, setActiveTab] = useState('explore');
  const [loadingMarkets, setLoadingMarkets] = useState(false);
  const [cart, setCart] = useState<Array<{ id: string; name: string; price: number }>>([]);
  const [showCart, setShowCart] = useState(false);
  const [showRegisterModal, setShowRegisterModal] = useState(false);
  const [showPayment, setShowPayment] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [showLocationPrompt, setShowLocationPrompt] = useState(false);
  const [appReady, setAppReady] = useState(false);

  const [allFarmers, setAllFarmers] = useState<Farmer[]>([]);
  const [markets, setMarkets] = useState<Market[]>(MARKETS);
  const [userLocation, setUserLocation] = useState<GeolocationPosition | null>(null);
  const [purchaseHistory, setPurchaseHistory] = useState<PurchaseHistoryItem[]>([]);
  const [userStats, setUserStats] = useState<UserStats>({
    marketsVisited: 0,
    co2SavedKg: 0,
    localEconomySupport: 0,
    badgesEarned: 0
  });

  // Initialize App from "Backend"
  useEffect(() => {
    const init = async () => {
      const session = await db.getSession();
      const farmers = await db.getFarmers();
      setAllFarmers(farmers);

      if (session) {
        setUserName(session.name);
        setIsLoggedIn(true);
        const stats = await db.getUserStats(session.name);
        const history = await db.getPurchaseHistory(session.name);
        setUserStats(stats);
        setPurchaseHistory(history);
      }
      setAppReady(true);
    };
    init();
  }, []);

  const handleLogin = async (name: string) => {
    setUserName(name);
    setIsLoggedIn(true);
    const stats = await db.getUserStats(name);
    const history = await db.getPurchaseHistory(name);
    const farmers = await db.getFarmers();
    setUserStats(stats);
    setPurchaseHistory(history);
    setAllFarmers(farmers);
    setShowLocationPrompt(true);
  };

  const handleLogout = async () => {
    await db.logout();
    setIsLoggedIn(false);
    setUserName('');
    setPurchaseHistory([]);
    setCart([]);
  };

  const fetchNearbyMarkets = async (pos: GeolocationPosition) => {
    setUserLocation(pos);
    setShowLocationPrompt(false);
    setLoadingMarkets(true);
    try {
      const nearby = await getNearbyMarkets(pos.coords.latitude, pos.coords.longitude);
      if (nearby && Array.isArray(nearby)) {
        setMarkets(nearby);
        const updatedStats = { ...userStats, marketsVisited: nearby.length };
        setUserStats(updatedStats);
        await db.saveUserStats(userName, updatedStats);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingMarkets(false);
    }
  };

  const addToCart = (product: any) => {
    setCart(prev => [...prev, { id: product.id, name: product.name, price: product.price }]);
    const toast = document.createElement('div');
    toast.className = 'fixed bottom-10 right-10 bg-emerald-600 text-white px-6 py-3 rounded-full text-sm font-bold shadow-2xl z-[1000] animate-bounce';
    toast.innerText = `Added ${product.name} to Bag! 🛍️`;
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 2000);
  };

  const onPaymentSuccess = async () => {
    const total = cartTotal;
    const items = cart.map(c => c.name);

    const updatedStats = {
      ...userStats,
      localEconomySupport: userStats.localEconomySupport + total,
      co2SavedKg: userStats.co2SavedKg + (total / 100 * 0.4) 
    };

    setUserStats(updatedStats);
    await db.saveUserStats(userName, updatedStats);

    const newRecord: PurchaseHistoryItem = {
      id: Math.floor(Math.random() * 1000000).toString(),
      date: new Date().toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }),
      items: items,
      total: total
    };

    const updatedHistory = await db.saveOrder(userName, newRecord);
    setPurchaseHistory(updatedHistory);

    setShowPayment(false);
    setCart([]);
    setShowCart(false);
    alert(`Success! ₹${total} paid to our Farmer partners. Thank you for buying local!`);
  };

  const cartTotal = cart.reduce((sum, item) => sum + item.price, 0);

  const renderProductGrid = (products: Product[]) => (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
      {products.map(product => (
        <div key={product.id} className="bg-white rounded-[2rem] border border-stone-100 overflow-hidden group hover:shadow-xl transition-all flex flex-col">
          <div className="h-48 overflow-hidden relative">
            <img src={product.image} alt={product.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
            <div className="absolute inset-0 bg-black/5 group-hover:bg-transparent transition-colors"></div>
          </div>
          <div className="p-6 flex-1 flex flex-col">
            <h4 className="font-black text-stone-800 mb-1 text-lg">{product.name}</h4>
            <div className="flex justify-between items-center mb-6">
              <span className="text-emerald-700 font-black text-xl">₹{product.price}</span>
              <span className="text-xs text-stone-400 font-bold uppercase tracking-wider">/{product.unit}</span>
            </div>
            <button 
              onClick={() => addToCart(product)}
              className="mt-auto w-full bg-stone-900 text-white font-black py-4 rounded-2xl text-sm hover:bg-emerald-600 transition-all shadow-xl shadow-stone-100"
            >
              Add to Bag
            </button>
          </div>
        </div>
      ))}
    </div>
  );

  const renderContent = () => {
    switch (activeTab) {
      case 'explore':
        const vegetables = PRODUCTS.filter(p => p.category === 'Vegetables');
        const fruits = PRODUCTS.filter(p => p.category === 'Fruits');
        return (
          <div className="space-y-12 pb-24 md:pb-12">
            <header className="flex flex-col md:flex-row md:items-end justify-between gap-6">
              <div className="flex-1">
                <h2 className="text-4xl font-extrabold text-stone-900 tracking-tight mb-2">Namaste, {userName}</h2>
                <div className="flex items-center gap-3">
                  <p className="text-emerald-600 font-bold text-xl">Supporting local Indian Farmers.</p>
                  {loadingMarkets && <i className="fa-solid fa-spinner animate-spin text-emerald-500"></i>}
                </div>
                {userLocation && (
                  <p className="text-stone-400 text-xs mt-2 font-bold flex items-center gap-2">
                    <i className="fa-solid fa-location-arrow text-emerald-500"></i> Localizing for your current area...
                  </p>
                )}
              </div>
              <div className="flex gap-4">
                <button 
                  onClick={() => setShowCart(!showCart)}
                  className={`relative p-5 rounded-3xl shadow-lg transition-all border-2 flex items-center gap-3 ${showCart ? 'bg-emerald-600 border-emerald-600 text-white' : 'bg-white border-stone-100 text-emerald-600'}`}
                >
                  <i className="fa-solid fa-bag-shopping text-2xl"></i>
                  {cart.length > 0 && <span className="absolute -top-3 -right-3 bg-red-500 text-white text-[11px] font-black w-8 h-8 flex items-center justify-center rounded-full border-4 border-white shadow-xl">{cart.length}</span>}
                  <span className={`font-black hidden md:inline ${showCart ? 'text-white' : 'text-stone-700'}`}>₹{cartTotal}</span>
                </button>
              </div>
            </header>

            {showCart && (
              <div className="bg-white rounded-[3rem] p-10 border border-emerald-100 shadow-2xl animate-in fade-in slide-in-from-top-6 duration-300">
                <div className="flex justify-between items-center mb-8">
                  <h3 className="text-2xl font-black text-stone-800">My Fresh Harvest</h3>
                  <button onClick={() => setCart([])} className="text-xs text-red-500 font-black uppercase tracking-widest hover:underline">Clear Items</button>
                </div>
                {cart.length === 0 ? (
                  <div className="text-center py-10 bg-stone-50 rounded-[2rem] border-2 border-dashed border-stone-200">
                    <i className="fa-solid fa-cart-arrow-down text-4xl text-stone-200 mb-4 block"></i>
                    <p className="text-stone-400 font-bold">Your shopping bag is empty.</p>
                  </div>
                ) : (
                  <>
                    <div className="space-y-4 mb-10 max-h-72 overflow-y-auto pr-4 scrollbar-hide">
                      {cart.map((item, idx) => (
                        <div key={idx} className="flex justify-between items-center py-3 border-b border-stone-50 last:border-0">
                          <span className="text-stone-700 font-bold">{item.name}</span>
                          <span className="font-black text-stone-900">₹{item.price}</span>
                        </div>
                      ))}
                    </div>
                    <div className="flex justify-between items-center mb-10 bg-emerald-50 p-8 rounded-[2.5rem] border border-emerald-100">
                      <span className="font-black text-stone-700 text-xl">Total To Pay</span>
                      <span className="font-black text-emerald-700 text-4xl">₹{cartTotal}</span>
                    </div>
                    <button onClick={() => setShowPayment(true)} className="w-full bg-emerald-600 text-white font-black py-6 rounded-3xl hover:bg-emerald-700 transition-all shadow-2xl shadow-emerald-100 text-xl">Confirm Order</button>
                  </>
                )}
              </div>
            )}

            {markets.length > 0 && (
              <section className="bg-gradient-to-br from-emerald-50 to-white p-8 rounded-[3rem] border border-emerald-100 shadow-sm animate-in fade-in duration-1000">
                <h3 className="text-2xl font-black text-stone-800 mb-6 flex items-center gap-3">
                  <div className="bg-emerald-200 w-10 h-10 rounded-xl flex items-center justify-center">
                    <i className="fa-solid fa-map-location-dot text-emerald-700"></i>
                  </div>
                  Mandis Found In Your Region
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {markets.slice(0, 3).map(m => (
                    <div key={m.id} className="bg-white p-6 rounded-3xl shadow-sm border border-stone-100 hover:scale-[1.02] transition-transform">
                       <h4 className="font-black text-stone-800">{m.name}</h4>
                       <p className="text-xs text-stone-400 mt-1 mb-4 flex items-center gap-1"><i className="fa-solid fa-location-dot"></i> {m.distance} away</p>
                       <p className="text-[10px] font-black uppercase text-emerald-600 bg-emerald-50 px-2 py-1 rounded inline-block">Active: {m.hours}</p>
                    </div>
                  ))}
                </div>
              </section>
            )}

            <section>
              <h3 className="text-2xl font-black text-stone-800 mb-8 flex items-center gap-3">
                <div className="bg-orange-100 w-10 h-10 rounded-xl flex items-center justify-center"><i className="fa-solid fa-carrot text-orange-600"></i></div>
                Pure Vegetables
              </h3>
              {renderProductGrid(vegetables)}
            </section>

            <section>
              <h3 className="text-2xl font-black text-stone-800 mb-8 flex items-center gap-3">
                <div className="bg-red-100 w-10 h-10 rounded-xl flex items-center justify-center"><i className="fa-solid fa-apple-whole text-red-600"></i></div>
                Fresh Seasonal Fruits
              </h3>
              {renderProductGrid(fruits)}
            </section>
          </div>
        );
      case 'markets':
        return (
          <div className="space-y-8 pb-24 md:pb-12">
            <h2 className="text-3xl font-black text-stone-900 mb-2">Explore Nearby Mandis</h2>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              {markets.map(market => <MarketCard key={market.id} market={market} />)}
            </div>
          </div>
        );
      case 'farmers':
        return (
          <div className="space-y-8 pb-24 md:pb-12">
            <h2 className="text-3xl font-black text-stone-900 mb-2">Farmer Community</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {allFarmers.map(farmer => <FarmerCard key={farmer.id} farmer={farmer} />)}
              <div 
                onClick={() => setShowRegisterModal(true)}
                className="bg-emerald-50 rounded-[2.5rem] p-8 border-2 border-dashed border-emerald-200 flex flex-col items-center justify-center text-center group cursor-pointer hover:bg-emerald-100 transition-colors h-full min-h-[350px]"
              >
                <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mb-4 shadow-sm group-hover:scale-110 transition-transform">
                  <i className="fa-solid fa-plus text-emerald-600 text-2xl"></i>
                </div>
                <h3 className="text-xl font-black text-emerald-900">Are you a Farmer?</h3>
                <p className="text-emerald-700 font-medium mb-6">Create your profile and start selling directly.</p>
                <button className="bg-emerald-700 text-white font-bold py-3 px-8 rounded-xl shadow-lg">Join Community</button>
              </div>
            </div>
          </div>
        );
      case 'kitchen': return <AIKitchen />;
      case 'stats': return <ImpactStats stats={userStats} />;
      default: return null;
    }
  };

  if (!appReady) {
    return (
      <div className="fixed inset-0 bg-stone-50 flex flex-col items-center justify-center">
        <i className="fa-solid fa-leaf text-5xl text-emerald-600 animate-bounce mb-4"></i>
        <p className="text-stone-400 font-bold animate-pulse">Connecting to HarvestHub Backend...</p>
      </div>
    );
  }

  if (!isLoggedIn) {
    return <Auth onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen md:pl-64">
      <Navigation 
        activeTab={activeTab} setActiveTab={setActiveTab} 
        onLogout={handleLogout}
      />
      <main className="max-w-7xl mx-auto p-6 md:p-12">
        {renderContent()}
      </main>

      {showLocationPrompt && (
        <LocationPrompt 
          onGrant={(pos) => fetchNearbyMarkets(pos)} 
          onSkip={() => setShowLocationPrompt(false)} 
        />
      )}

      {showRegisterModal && (
        <FarmerRegistration 
          onClose={() => setShowRegisterModal(false)} 
          onAdd={(newFarmer) => setAllFarmers(prev => [newFarmer, ...prev])} 
        />
      )}
      {showPayment && <PaymentGateway total={cartTotal} onCancel={() => setShowPayment(false)} onSuccess={onPaymentSuccess} />}
      {showHistory && <HistoryModal history={purchaseHistory} onClose={() => setShowHistory(false)} />}

      <button 
        onClick={() => setShowHistory(true)}
        className="md:hidden fixed bottom-24 right-6 w-14 h-14 bg-stone-900 text-white rounded-full shadow-2xl z-40 flex items-center justify-center"
      >
        <i className="fa-solid fa-clock-rotate-left"></i>
      </button>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import Navigation from './components/Navigation';
import MarketCard from './components/MarketCard';
import FarmerCard from './components/FarmerCard';
import ImpactStats from './components/ImpactStats';
import AIKitchen from './components/AIKitchen';
import { db } from './services/database';
import { getNearbyMarkets } from './services/geminiService';
import { Farmer, Market, UserStats, PurchaseHistoryItem, Product } from './types';
import { PRODUCTS, MARKETS } from './constants';

// --- AUTH COMPONENTS ---

const Auth: React.FC<{ onLogin: (name: string) => void }> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [name, setName] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      if (isLogin) {
        await db.loginUser(name, password);
        onLogin(name);
      } else {
        await db.registerUser(name, password);
        onLogin(name);
      }
    } catch (err: any) {
      setError(err.message || 'Something went wrong');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-emerald-900 flex items-center justify-center p-6 z-[999]">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] p-10 shadow-2xl animate-in fade-in zoom-in duration-500">
        <div className="flex flex-col items-center mb-10">
          <div className="bg-emerald-600 p-4 rounded-3xl mb-4 shadow-lg">
            <i className="fa-solid fa-leaf text-3xl text-white"></i>
          </div>
          <h1 className="text-3xl font-black text-stone-900 tracking-tight">HarvestHub</h1>
          <p className="text-stone-500 font-medium text-center">Support your local Farmers</p>
        </div>

        <form onSubmit={handleAuth} className="space-y-6">
          <div>
            <label className="block text-xs font-black text-stone-400 uppercase tracking-widest mb-2">User Name</label>
            <input 
              type="text" required placeholder="Enter your name" 
              className="w-full bg-stone-50 border border-stone-200 rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-emerald-500"
              value={name} onChange={(e) => setName(e.target.value)}
              disabled={loading}
            />
          </div>
          <div>
            <label className="block text-xs font-black text-stone-400 uppercase tracking-widest mb-2">Password</label>
            <input 
              type="password" required placeholder="Create/Enter password" 
              className="w-full bg-stone-50 border border-stone-200 rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-emerald-500"
              value={password} onChange={(e) => setPassword(e.target.value)}
              disabled={loading}
            />
          </div>
          {error && <p className="text-red-500 text-xs font-bold text-center">{error}</p>}
          <button type="submit" disabled={loading} className="w-full bg-emerald-600 text-white font-black py-4 rounded-2xl hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-100 disabled:opacity-50">
            {loading ? <i className="fa-solid fa-circle-notch animate-spin"></i> : (isLogin ? 'Login' : 'Join HarvestHub')}
          </button>
        </form>

        <div className="mt-8 pt-8 border-t border-stone-100 text-center">
          <button onClick={() => { setIsLogin(!isLogin); setError(''); }} className="text-emerald-600 font-black text-sm hover:underline" disabled={loading}>
            {isLogin ? "Don't have an account? Sign Up" : "Already have an account? Login"}
          </button>
        </div>
      </div>
    </div>
  );
};

// --- LOCATION ONBOARDING ---

const LocationPrompt: React.FC<{ onGrant: (pos: GeolocationPosition) => void; onSkip: () => void }> = ({ onGrant, onSkip }) => {
  const [requesting, setRequesting] = useState(false);

  const handleRequest = () => {
    setRequesting(true);
    navigator.geolocation.getCurrentPosition(
      (pos) => { onGrant(pos); },
      (err) => { 
        console.error(err);
        setRequesting(false);
        alert("Location access denied. You can still browse, but we won't be able to find your local markets.");
        onSkip();
      },
      { timeout: 10000 }
    );
  };

  return (
    <div className="fixed inset-0 bg-stone-900/60 backdrop-blur-md z-[800] flex items-center justify-center p-6">
      <div className="bg-white w-full max-w-lg rounded-[3rem] p-12 text-center shadow-2xl">
        <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center mx-auto mb-8 animate-bounce">
          <i className="fa-solid fa-location-dot text-4xl text-emerald-600"></i>
        </div>
        <h2 className="text-3xl font-black text-stone-900 mb-4">Find Your Local Markets</h2>
        <p className="text-stone-500 font-medium mb-10 leading-relaxed">
          Allow location access to discover fresh products from farmers right in your neighborhood. Help us support your local kisan!
        </p>
        <div className="space-y-4">
          <button 
            onClick={handleRequest}
            disabled={requesting}
            className="w-full bg-emerald-600 text-white font-black py-5 rounded-3xl hover:bg-emerald-700 shadow-xl shadow-emerald-100 transition-all text-lg flex items-center justify-center gap-3"
          >
            {requesting ? <i className="fa-solid fa-spinner animate-spin"></i> : <i className="fa-solid fa-compass"></i>}
            Enable Location
          </button>
          <button onClick={onSkip} className="text-stone-400 font-bold hover:text-stone-600">Maybe Later</button>
        </div>
      </div>
    </div>
  );
};

// --- FARMER REGISTRATION COMPONENT ---
const FarmerRegistration: React.FC<{ onClose: () => void; onAdd: (f: Farmer) => void }> = ({ onClose, onAdd }) => {
  const [name, setName] = useState('');
  const [farmName, setFarmName] = useState('');
  const [bio, setBio] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const newFarmer: Farmer = {
      id: 'f' + Date.now(),
      name,
      farmName,
      bio,
      location: 'Local Region',
      rating: 5.0,
      image: `https://images.unsplash.com/photo-${Math.floor(Math.random() * 1000000)}?auto=format&fit=crop&q=80&w=400&h=400`,
      specialties: ['Organic Produce'],
      contact: '+91 9XXXX-XXXXX'
    };
    await db.addFarmer(newFarmer);
    onAdd(newFarmer);
    setLoading(false);
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-stone-900/60 backdrop-blur-sm z-[1000] flex items-center justify-center p-6">
      <div className="bg-white w-full max-w-lg rounded-[3rem] p-10 shadow-2xl relative animate-in fade-in zoom-in duration-300">
        <button onClick={onClose} className="absolute top-8 right-8 text-stone-300 hover:text-stone-900">
          <i className="fa-solid fa-xmark text-xl"></i>
        </button>
        <h2 className="text-3xl font-black text-stone-900 mb-8">Farmer Registration</h2>
        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label className="block text-xs font-black text-stone-400 uppercase tracking-widest mb-2">Full Name</label>
            <input required placeholder="Your Name" className="w-full bg-stone-50 border border-stone-200 rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-emerald-500" value={name} onChange={e => setName(e.target.value)} />
          </div>
          <div>
            <label className="block text-xs font-black text-stone-400 uppercase tracking-widest mb-2">Farm Name</label>
            <input required placeholder="Example: Kisan Organic" className="w-full bg-stone-50 border border-stone-200 rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-emerald-500" value={farmName} onChange={e => setFarmName(e.target.value)} />
          </div>
          <div>
            <label className="block text-xs font-black text-stone-400 uppercase tracking-widest mb-2">Bio / Story</label>
            <textarea required placeholder="Tell us about your farm..." className="w-full bg-stone-50 border border-stone-200 rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-emerald-500 min-h-[100px]" value={bio} onChange={e => setBio(e.target.value)} />
          </div>
          <button type="submit" disabled={loading} className="w-full bg-emerald-600 text-white font-black py-4 rounded-2xl hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-100">
            {loading ? <i className="fa-solid fa-circle-notch animate-spin mr-2"></i> : null}
            Submit Profile
          </button>
        </form>
      </div>
    </div>
  );
};

// --- PAYMENT GATEWAY COMPONENT ---
const PaymentGateway: React.FC<{ total: number; onCancel: () => void; onSuccess: () => void }> = ({ total, onCancel, onSuccess }) => {
  const [processing, setProcessing] = useState(false);
  const [upiId, setUpiId] = useState('');
  const [requestSent, setRequestSent] = useState(false);
  const receiverUpi = "harvesthub@okaxis";

  const handlePay = (e: React.FormEvent) => {
    e.preventDefault();
    if (!upiId) return;
    setProcessing(true);
    // Simulate sending request to the user's UPI app
    setTimeout(() => {
      setRequestSent(true);
      setProcessing(false);
      // Simulate user confirming in their app after a delay
      setTimeout(() => {
        onSuccess();
      }, 3000);
    }, 2000);
  };

  return (
    <div className="fixed inset-0 bg-stone-900/80 backdrop-blur-xl z-[2000] flex items-center justify-center p-6">
      <div className="bg-white w-full max-w-md rounded-[3rem] p-10 text-center shadow-2xl relative">
        <div className="w-20 h-20 bg-emerald-100 rounded-full flex items-center justify-center mx-auto mb-6">
          <i className="fa-solid fa-shield-halved text-3xl text-emerald-600"></i>
        </div>

        {!requestSent ? (
          <>
            <h3 className="text-2xl font-black text-stone-900 mb-2">Secure UPI Payment</h3>
            <p className="text-stone-500 mb-6 font-medium">Paying ₹{total} to Farmers</p>

            <div className="bg-emerald-50 p-4 rounded-2xl mb-8 border border-emerald-100 text-left">
              <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest mb-1">Receiver UPI ID</p>
              <p className="font-black text-emerald-900">{receiverUpi}</p>
            </div>

            <form onSubmit={handlePay} className="space-y-4">
              <div className="text-left">
                <label className="text-[10px] font-black text-stone-400 uppercase tracking-widest block mb-2">Enter Your UPI ID</label>
                <input 
                  required
                  type="text" 
                  placeholder="example@upi" 
                  value={upiId}
                  onChange={(e) => setUpiId(e.target.value)}
                  className="w-full bg-stone-50 border border-stone-200 rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-emerald-500"
                  disabled={processing}
                />
              </div>
              <button 
                type="submit"
                disabled={processing || !upiId}
                className="w-full bg-emerald-600 text-white font-black py-5 rounded-3xl flex items-center justify-center gap-3 hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-100 disabled:opacity-50"
              >
                {processing ? <i className="fa-solid fa-circle-notch animate-spin"></i> : <i className="fa-solid fa-paper-plane"></i>}
                {processing ? 'Connecting...' : 'Send Payment Request'}
              </button>
              <button type="button" onClick={onCancel} className="text-stone-400 font-bold hover:text-stone-600">Cancel</button>
            </form>
          </>
        ) : (
          <div className="py-8 animate-in fade-in duration-500">
            <div className="relative w-24 h-24 mx-auto mb-8">
               <div className="absolute inset-0 border-4 border-stone-100 rounded-full"></div>
               <div className="absolute inset-0 border-4 border-emerald-500 rounded-full border-t-transparent animate-spin"></div>
               <div className="absolute inset-0 flex items-center justify-center">
                  <i className="fa-solid fa-mobile-screen-button text-2xl text-emerald-600"></i>
               </div>
            </div>
            <h3 className="text-2xl font-black text-stone-900 mb-2">Check Your UPI App</h3>
            <p className="text-stone-500 font-medium">We've sent a request to <span className="font-black text-stone-800">{upiId}</span>. Please authorize the payment of ₹{total} to complete your order.</p>
            <p className="mt-8 text-[10px] font-black text-stone-300 uppercase tracking-widest">Waiting for confirmation...</p>
          </div>
        )}
      </div>
    </div>
  );
};

