// --- APP COMPONENT ---

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [userName, setUserName] = useState('');
  const [activeTab, setActiveTab] = useState('explore');
  const [loadingMarkets, setLoadingMarkets] = useState(false);
  const [cart, setCart] = useState<Array<{ id: string; name: string; price: number }>>([]);
  const [showCart, setShowCart] = useState(false);
  const [showRegisterModal, setShowRegisterModal] = useState(false);
  const [showPayment, setShowPayment] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [showLocationPrompt, setShowLocationPrompt] = useState(false);
  const [appReady, setAppReady] = useState(false);

  const [allFarmers, setAllFarmers] = useState<Farmer[]>([]);
  const [markets, setMarkets] = useState<Market[]>(MARKETS);
  const [userLocation, setUserLocation] = useState<GeolocationPosition | null>(null);
  const [purchaseHistory, setPurchaseHistory] = useState<PurchaseHistoryItem[]>([]);
  const [userStats, setUserStats] = useState<UserStats>({
    marketsVisited: 0,
    co2SavedKg: 0,
    localEconomySupport: 0,
    badgesEarned: 0
  });

  // Initialize App from "Backend"
  useEffect(() => {
    const init = async () => {
      const session = await db.getSession();
      const farmers = await db.getFarmers();
      setAllFarmers(farmers);

      if (session) {
        setUserName(session.name);
        setIsLoggedIn(true);
        const stats = await db.getUserStats(session.name);
        const history = await db.getPurchaseHistory(session.name);
        setUserStats(stats);
        setPurchaseHistory(history);
      }
      setAppReady(true);
    };
    init();
  }, []);

  const handleLogin = async (name: string) => {
    setUserName(name);
    setIsLoggedIn(true);
    const stats = await db.getUserStats(name);
    const history = await db.getPurchaseHistory(name);
    const farmers = await db.getFarmers();
    setUserStats(stats);
    setPurchaseHistory(history);
    setAllFarmers(farmers);
    setShowLocationPrompt(true);
  };

  const handleLogout = async () => {
    await db.logout();
    setIsLoggedIn(false);
    setUserName('');
    setPurchaseHistory([]);
    setCart([]);
    setShowCart(false);
  };

  const fetchNearbyMarkets = async (pos: GeolocationPosition) => {
    setUserLocation(pos);
    setShowLocationPrompt(false);
    setLoadingMarkets(true);
    try {
      const nearby = await getNearbyMarkets(pos.coords.latitude, pos.coords.longitude);
      if (nearby && Array.isArray(nearby)) {
        setMarkets(nearby);
        const updatedStats = { ...userStats, marketsVisited: nearby.length };
        setUserStats(updatedStats);
        await db.saveUserStats(userName, updatedStats);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingMarkets(false);
    }
  };

  const addToCart = (product: any) => {
    setCart(prev => [...prev, { id: product.id, name: product.name, price: product.price }]);
    const toast = document.createElement('div');
    toast.className = 'fixed bottom-10 right-10 bg-emerald-600 text-white px-6 py-3 rounded-full text-sm font-bold shadow-2xl z-[1000] animate-bounce';
    toast.innerText = `Added ${product.name} to Bag! 🛍️`;
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 2000);
  };

  const onPaymentSuccess = async () => {
    const total = cartTotal;
    const items = cart.map(c => c.name);

    const updatedStats = {
      ...userStats,
      localEconomySupport: userStats.localEconomySupport + total,
      co2SavedKg: userStats.co2SavedKg + (total / 100 * 0.4) 
    };

    setUserStats(updatedStats);
    await db.saveUserStats(userName, updatedStats);

    const newRecord: PurchaseHistoryItem = {
      id: Math.floor(Math.random() * 1000000).toString(),
      date: new Date().toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }),
      items: items,
      total: total
    };

    const updatedHistory = await db.saveOrder(userName, newRecord);
    setPurchaseHistory(updatedHistory);

    setShowPayment(false);
    setCart([]);
    setShowCart(false);
    alert(`Success! ₹${total} paid to our Farmer partners. Thank you for buying local!`);
  };

  const cartTotal = cart.reduce((sum, item) => sum + item.price, 0);

  const renderProductGrid = (products: Product[]) => (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
      {products.map(product => (
        <div key={product.id} className="bg-white rounded-[2rem] border border-stone-100 overflow-hidden group hover:shadow-xl transition-all flex flex-col">
          <div className="h-48 overflow-hidden relative">
            <img src={product.image} alt={product.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
            <div className="absolute inset-0 bg-black/5 group-hover:bg-transparent transition-colors"></div>
          </div>
          <div className="p-6 flex-1 flex flex-col">
            <h4 className="font-black text-stone-800 mb-1 text-lg">{product.name}</h4>
            <div className="flex justify-between items-center mb-6">
              <span className="text-emerald-700 font-black text-xl">₹{product.price}</span>
              <span className="text-xs text-stone-400 font-bold uppercase tracking-wider">/{product.unit}</span>
            </div>
            <button 
              onClick={() => addToCart(product)}
              className="mt-auto w-full bg-stone-900 text-white font-black py-4 rounded-2xl text-sm hover:bg-emerald-600 transition-all shadow-xl shadow-stone-100"
            >
              Add to Bag
            </button>
          </div>
        </div>
      ))}
    </div>
  );

  const renderContent = () => {
    switch (activeTab) {
      case 'explore':
        const vegetables = PRODUCTS.filter(p => p.category === 'Vegetables');
        const fruits = PRODUCTS.filter(p => p.category === 'Fruits');
        return (
          <div className="space-y-12 pb-24 md:pb-12">
            <header className="flex flex-col md:flex-row md:items-end justify-between gap-6">
              <div className="flex-1">
                <h2 className="text-4xl font-extrabold text-stone-900 tracking-tight mb-2">Namaste, {userName}</h2>
                <div className="flex items-center gap-3">
                  <p className="text-emerald-600 font-bold text-xl">Supporting local Indian Farmers.</p>
                  {loadingMarkets && <i className="fa-solid fa-spinner animate-spin text-emerald-500"></i>}
                </div>
                {userLocation && (
                  <p className="text-stone-400 text-xs mt-2 font-bold flex items-center gap-2">
                    <i className="fa-solid fa-location-arrow text-emerald-500"></i> Localizing for your current area...
                  </p>
                )}
              </div>
              <div className="flex gap-4">
                <button 
                  onClick={() => setShowCart(!showCart)}
                  className={`relative p-5 rounded-3xl shadow-lg transition-all border-2 flex items-center gap-3 ${showCart ? 'bg-emerald-600 border-emerald-600 text-white' : 'bg-white border-stone-100 text-emerald-600'}`}
                >
                  <i className="fa-solid fa-bag-shopping text-2xl"></i>
                  {cart.length > 0 && <span className="absolute -top-3 -right-3 bg-red-500 text-white text-[11px] font-black w-8 h-8 flex items-center justify-center rounded-full border-4 border-white shadow-xl">{cart.length}</span>}
                  <span className={`font-black hidden md:inline ${showCart ? 'text-white' : 'text-stone-700'}`}>₹{cartTotal}</span>
                </button>
              </div>
            </header>

            {showCart && (
              <div className="bg-white rounded-[3rem] p-10 border border-emerald-100 shadow-2xl animate-in fade-in slide-in-from-top-6 duration-300">
                <div className="flex justify-between items-center mb-8">
                  <h3 className="text-2xl font-black text-stone-800">My Fresh Harvest</h3>
                  <button onClick={() => setCart([])} className="text-xs text-red-500 font-black uppercase tracking-widest hover:underline">Clear Items</button>
                </div>
                {cart.length === 0 ? (
                  <div className="text-center py-10 bg-stone-50 rounded-[2rem] border-2 border-dashed border-stone-200">
                    <i className="fa-solid fa-cart-arrow-down text-4xl text-stone-200 mb-4 block"></i>
                    <p className="text-stone-400 font-bold">Your shopping bag is empty.</p>
                  </div>
                ) : (
                  <>
                    <div className="space-y-4 mb-10 max-h-72 overflow-y-auto pr-4 scrollbar-hide">
                      {cart.map((item, idx) => (
                        <div key={idx} className="flex justify-between items-center py-3 border-b border-stone-50 last:border-0">
                          <span className="text-stone-700 font-bold">{item.name}</span>
                          <span className="font-black text-stone-900">₹{item.price}</span>
                        </div>
                      ))}
                    </div>
                    <div className="flex justify-between items-center mb-10 bg-emerald-50 p-8 rounded-[2.5rem] border border-emerald-100">
                      <span className="font-black text-stone-700 text-xl">Total To Pay</span>
                      <span className="font-black text-emerald-700 text-4xl">₹{cartTotal}</span>
                    </div>
                    <button onClick={() => setShowPayment(true)} className="w-full bg-emerald-600 text-white font-black py-6 rounded-3xl hover:bg-emerald-700 transition-all shadow-2xl shadow-emerald-100 text-xl">Confirm Order</button>
                  </>
                )}
              </div>
            )}

            {markets.length > 0 && (
              <section className="bg-gradient-to-br from-emerald-50 to-white p-8 rounded-[3rem] border border-emerald-100 shadow-sm animate-in fade-in duration-1000">
                <h3 className="text-2xl font-black text-stone-800 mb-6 flex items-center gap-3">
                  <div className="bg-emerald-200 w-10 h-10 rounded-xl flex items-center justify-center">
                    <i className="fa-solid fa-map-location-dot text-emerald-700"></i>
                  </div>
                  Markets Found In Your Region
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {markets.slice(0, 3).map(m => (
                    <div key={m.id} className="bg-white p-6 rounded-3xl shadow-sm border border-stone-100 hover:scale-[1.02] transition-transform">
                       <h4 className="font-black text-stone-800">{m.name}</h4>
                       <p className="text-xs text-stone-400 mt-1 mb-4 flex items-center gap-1"><i className="fa-solid fa-location-dot"></i> {m.distance} away</p>
                       <p className="text-[10px] font-black uppercase text-emerald-600 bg-emerald-50 px-2 py-1 rounded inline-block">Active: {m.hours}</p>
                    </div>
                  ))}
                </div>
              </section>
            )}

            <section>
              <h3 className="text-2xl font-black text-stone-800 mb-8 flex items-center gap-3">
                <div className="bg-orange-100 w-10 h-10 rounded-xl flex items-center justify-center"><i className="fa-solid fa-carrot text-orange-600"></i></div>
                Pure Vegetables
              </h3>
              {renderProductGrid(vegetables)}
            </section>

            <section>
              <h3 className="text-2xl font-black text-stone-800 mb-8 flex items-center gap-3">
                <div className="bg-red-100 w-10 h-10 rounded-xl flex items-center justify-center"><i className="fa-solid fa-apple-whole text-red-600"></i></div>
                Fresh Seasonal Fruits
              </h3>
              {renderProductGrid(fruits)}
            </section>
          </div>
        );
      case 'markets':
        return (
          <div className="space-y-8 pb-24 md:pb-12">
            <h2 className="text-3xl font-black text-stone-900 mb-2">Explore Nearby Markets</h2>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              {markets.map(market => <MarketCard key={market.id} market={market} />)}
            </div>
          </div>
        );
      case 'farmers':
        return (
          <div className="space-y-8 pb-24 md:pb-12">
            <h2 className="text-3xl font-black text-stone-900 mb-2">Farmer Community</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {allFarmers.map(farmer => <FarmerCard key={farmer.id} farmer={farmer} />)}
              <div 
                onClick={() => setShowRegisterModal(true)}
                className="bg-emerald-50 rounded-[2.5rem] p-8 border-2 border-dashed border-emerald-200 flex flex-col items-center justify-center text-center group cursor-pointer hover:bg-emerald-100 transition-colors h-full min-h-[350px]"
              >
                <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mb-4 shadow-sm group-hover:scale-110 transition-transform">
                  <i className="fa-solid fa-plus text-emerald-600 text-2xl"></i>
                </div>
                <h3 className="text-xl font-black text-emerald-900">Are you a Farmer?</h3>
                <p className="text-emerald-700 font-medium mb-6">Create your profile and start selling directly.</p>
                <button className="bg-emerald-700 text-white font-bold py-3 px-8 rounded-xl shadow-lg">Join Community</button>
              </div>
            </div>
          </div>
        );
      case 'kitchen': return <AIKitchen />;
      case 'stats': return <ImpactStats stats={userStats} />;
      default: return null;
    }
  };

  if (!appReady) {
    return (
      <div className="fixed inset-0 bg-stone-50 flex flex-col items-center justify-center">
        <i className="fa-solid fa-leaf text-5xl text-emerald-600 animate-bounce mb-4"></i>
        <p className="text-stone-400 font-bold animate-pulse">Connecting to HarvestHub Backend...</p>
      </div>
    );
  }

  if (!isLoggedIn) {
    return <Auth onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen md:pl-64">
      <Navigation 
        activeTab={activeTab} setActiveTab={setActiveTab} 
        onLogout={handleLogout}
      />
      <main className="max-w-7xl mx-auto p-6 md:p-12">
        {renderContent()}
      </main>

      {showLocationPrompt && (
        <LocationPrompt 
          onGrant={(pos) => fetchNearbyMarkets(pos)} 
          onSkip={() => setShowLocationPrompt(false)} 
        />
      )}

      {showRegisterModal && (
        <FarmerRegistration 
          onClose={() => setShowRegisterModal(false)} 
          onAdd={(newFarmer) => setAllFarmers(prev => [newFarmer, ...prev])} 
        />
      )}
      {showPayment && <PaymentGateway total={cartTotal} onCancel={() => setShowPayment(false)} onSuccess={onPaymentSuccess} />}
      {showHistory && <HistoryModal history={purchaseHistory} onClose={() => setShowHistory(false)} />}

      <button 
        onClick={() => setShowHistory(true)}
        className="md:hidden fixed bottom-24 right-6 w-14 h-14 bg-stone-900 text-white rounded-full shadow-2xl z-40 flex items-center justify-center"
      >
        <i className="fa-solid fa-clock-rotate-left"></i>
      </button>
    </div>
  );
};

export default App;

