      const farmers = await db.getFarmers();
      setAllFarmers(farmers);
      if (session) {
        setUserName(session.name);
        setIsLoggedIn(true);
        const stats = await db.getUserStats(session.name);
        const history = await db.getPurchaseHistory(session.name);
        setUserStats(stats);
        setPurchaseHistory(history);
      }
      setAppReady(true);
    };
    init();
  }, []);

  const handleLogin = (name: string) => {
    setUserName(name);
    setIsLoggedIn(true);
    setShowLocationPrompt(true);
  };

  const handleLogout = async () => {
    await db.logout();
    setIsLoggedIn(false);
    setCart([]);
  };

  const handleLocationGrant = async (pos: GeolocationPosition) => {
    setShowLocationPrompt(false);
    setLoadingMarkets(true);
    const dynamicMarkets = await getNearbyMarkets(pos.coords.latitude, pos.coords.longitude);
    if (dynamicMarkets && dynamicMarkets.length > 0) {
      setMarkets(dynamicMarkets);
    }
    setLoadingMarkets(false);
  };

  const addToCart = (product: Product) => {
    setCart(prev => [...prev, product]);
  };

  const onPaymentSuccess = async () => {
    const total = cart.reduce((sum, p) => sum + p.price, 0);
    const order: PurchaseHistoryItem = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      date: new Date().toLocaleDateString('en-IN'),
      items: cart.map(p => p.name),
      total: total,
      address: deliveryAddress
    };

    const updatedHistory = await db.saveOrder(userName, order);
    const newStats = {
      ...userStats,
      localEconomySupport: userStats.localEconomySupport + total,
      co2SavedKg: userStats.co2SavedKg + (total * 0.05),
      marketsVisited: userStats.marketsVisited + 1
    };
    await db.saveUserStats(userName, newStats);

    setPurchaseHistory(updatedHistory);
    setUserStats(newStats);
    setLatestOrder(order);
    setShowPayment(false);
    setCart([]);
    setShowCart(false);
  };

  if (!appReady) return <div className="min-h-screen flex items-center justify-center">Loading...</div>;
  if (!isLoggedIn) return <Auth onLogin={handleLogin} />;

  const cartTotal = cart.reduce((sum, p) => sum + p.price, 0);

  return (
    <div className="min-h-screen md:pl-64 bg-stone-50">
      <Navigation activeTab={activeTab} setActiveTab={setActiveTab} onLogout={handleLogout} />

      <main className="max-w-7xl mx-auto p-6 md:p-12">
        <header className="flex justify-between items-center mb-10">
          <h2 className="text-3xl font-black text-stone-900">Namaste, {userName}</h2>
          <button 
            onClick={() => setShowCart(!showCart)}
            className="bg-white border border-stone-100 p-4 rounded-3xl shadow-lg relative"
          >
            <i className="fa-solid fa-bag-shopping text-emerald-600 text-xl"></i>
            {cart.length > 0 && <span className="absolute -top-2 -right-2 bg-red-500 text-white text-[10px] w-6 h-6 rounded-full flex items-center justify-center font-black">{cart.length}</span>}
          </button>
        </header>

        {activeTab === 'explore' && (
          <div className="space-y-12">
            <section>
              <h3 className="text-xl font-black text-stone-800 mb-6">Seasonal Harvest</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {PRODUCTS.map(product => (
                  <div key={product.id} className="bg-white rounded-[2rem] border border-stone-100 overflow-hidden shadow-sm flex flex-col">
                    <img src={product.image} className="h-40 w-full object-cover" />
                    <div className="p-6 flex-1 flex flex-col">
                      <h4 className="font-bold text-stone-800">{product.name}</h4>
                      <p className="text-emerald-700 font-black mb-4">₹{product.price} / {product.unit}</p>
                      <button onClick={() => addToCart(product)} className="mt-auto w-full bg-stone-900 text-white font-black py-3 rounded-2xl text-xs hover:bg-emerald-600 transition-all">Add to Bag</button>
                    </div>
                  </div>
                ))}
              </div>
            </section>
          </div>
        )}

        {activeTab === 'farmers' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {allFarmers.map(farmer => <FarmerCard key={farmer.id} farmer={farmer} onAddToCart={addToCart} />)}
          </div>
        )}

        {activeTab === 'markets' && (
          <div className="space-y-8">
            <div className="bg-white p-6 rounded-3xl border border-stone-100 flex items-center gap-4">
              <div className="w-12 h-12 rounded-2xl bg-emerald-50 flex items-center justify-center text-emerald-600">
                <i className="fa-solid fa-location-arrow"></i>
              </div>
              <div>
                <p className="text-sm font-black text-stone-800">Markets Near You</p>
                <p className="text-xs text-stone-400">Discover real farmers' markets in your neighborhood.</p>
              </div>
            </div>
            {loadingMarkets ? (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {[1, 2].map(i => (
                  <div key={i} className="bg-stone-100 h-64 rounded-[2rem] animate-pulse"></div>
                ))}
              </div>
            ) : (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {markets.map(m => <MarketCard key={m.id} market={m} />)}
              </div>
            )}
          </div>
        )}

        {activeTab === 'kitchen' && <AIKitchen />}
        {activeTab === 'stats' && <ImpactStats stats={userStats} />}
      </main>

      {showCart && (
        <div className="fixed inset-y-0 right-0 w-full max-w-md bg-white shadow-2xl z-[1000] p-10 flex flex-col border-l border-stone-100 animate-in slide-in-from-right duration-300">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-2xl font-black">Shopping Bag</h3>
            <button onClick={() => setShowCart(false)}><i className="fa-solid fa-xmark"></i></button>
          </div>
          <div className="flex-1 overflow-y-auto space-y-4">
            {cart.map((item, idx) => (
              <div key={idx} className="flex justify-between items-center py-2 border-b border-stone-50">
                <span className="font-bold">{item.name}</span>
                <span className="font-black">₹{item.price}</span>
              </div>
            ))}
          </div>
          <div className="mt-8 pt-8 border-t border-stone-100">
            <div className="flex justify-between mb-8">
              <span className="font-black text-stone-500">Total</span>
              <span className="font-black text-2xl text-emerald-700">₹{cartTotal}</span>
            </div>
            <button 
              disabled={cart.length === 0}
              onClick={() => setShowAddressForm(true)} 
              className="w-full bg-emerald-600 text-white font-black py-5 rounded-3xl hover:bg-emerald-700 disabled:opacity-50"
