              Checkout
            </button>
          </div>
        </div>
      )}

      {showLocationPrompt && <LocationPrompt onGrant={handleLocationGrant} onSkip={() => setShowLocationPrompt(false)} />}
      {showAddressForm && <AddressForm total={cartTotal} onProceed={(addr) => { setDeliveryAddress(addr); setShowAddressForm(false); setShowPayment(true); }} onCancel={() => setShowAddressForm(false)} />}
      {showPayment && <PaymentGateway total={cartTotal} onCancel={() => setShowPayment(false)} onSuccess={onPaymentSuccess} />}
      {latestOrder && <Invoice order={latestOrder} userName={userName} onClose={() => setLatestOrder(null)} />}
      {showHistory && <HistoryModal history={purchaseHistory} onClose={() => setShowHistory(false)} />}

      <button onClick={() => setShowHistory(true)} className="fixed bottom-24 right-6 bg-stone-900 text-white p-4 rounded-full shadow-2xl z-40 md:hidden">
        <i className="fa-solid fa-clock-rotate-left"></i>
      </button>
    </div>
  );
};

