            className="w-full bg-emerald-600 text-white font-black py-5 rounded-3xl hover:bg-emerald-700 shadow-xl shadow-emerald-100 transition-all text-lg flex items-center justify-center gap-3"
          >
            {requesting ? <i className="fa-solid fa-spinner animate-spin"></i> : <i className="fa-solid fa-compass"></i>}
            Enable Location
          </button>
          <button onClick={onSkip} className="text-stone-400 font-bold hover:text-stone-600">Maybe Later</button>
        </div>
      </div>
    </div>
  );
};

// --- PAYMENT GATEWAY COMPONENT ---
const PaymentGateway: React.FC<{ total: number; onCancel: () => void; onSuccess: () => void }> = ({ total, onCancel, onSuccess }) => {
  const [processing, setProcessing] = useState(false);
  const [upiId, setUpiId] = useState('');
  const [requestSent, setRequestSent] = useState(false);

  const handlePay = (e: React.FormEvent) => {
    e.preventDefault();
    if (!upiId) return;
    setProcessing(true);
    setTimeout(() => {
      setRequestSent(true);
      setProcessing(false);
      setTimeout(() => {
        onSuccess();
      }, 3000);
    }, 2000);
  };

  return (
    <div className="fixed inset-0 bg-stone-900/80 backdrop-blur-xl z-[2000] flex items-center justify-center p-6">
      <div className="bg-white w-full max-w-md rounded-[3rem] p-10 text-center shadow-2xl relative">
        {!requestSent ? (
          <>
            <h3 className="text-2xl font-black text-stone-900 mb-2">Secure UPI Payment</h3>
            <p className="text-stone-500 mb-6 font-medium">Paying ₹{total} to Farmers</p>
            <form onSubmit={handlePay} className="space-y-4">
              <input 
                required
                type="text" 
                placeholder="example@upi" 
                value={upiId}
                onChange={(e) => setUpiId(e.target.value)}
                className="w-full bg-stone-50 border border-stone-200 rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-emerald-500"
                disabled={processing}
              />
              <button disabled={processing} className="w-full bg-emerald-600 text-white font-black py-5 rounded-3xl">
                {processing ? 'Processing...' : 'Pay Now'}
              </button>
              <button type="button" onClick={onCancel} className="text-stone-400 font-bold mt-4">Cancel</button>
            </form>
          </>
        ) : (
          <div className="py-8">
            <h3 className="text-2xl font-black text-stone-900 mb-2">Authorizing...</h3>
            <p className="text-stone-500">Please confirm the request in your UPI app.</p>
          </div>
        )}
      </div>
    </div>
  );
};

const HistoryModal: React.FC<{ history: PurchaseHistoryItem[]; onClose: () => void }> = ({ history, onClose }) => {
  return (
    <div className="fixed inset-0 bg-stone-900/60 backdrop-blur-sm z-[2000] flex items-center justify-center p-6">
      <div className="bg-white w-full max-w-2xl rounded-[3rem] p-10 shadow-2xl relative max-h-[80vh] overflow-y-auto">
        <button onClick={onClose} className="absolute top-8 right-8 text-stone-300 hover:text-stone-900">
          <i className="fa-solid fa-xmark text-xl"></i>
        </button>
        <h2 className="text-3xl font-black text-stone-900 mb-8">Purchase History</h2>
        {history.length === 0 ? <p className="text-stone-400 text-center py-10">No past orders.</p> : (
          <div className="space-y-4">
            {history.map(item => (
              <div key={item.id} className="bg-stone-50 p-6 rounded-[2rem] border border-stone-100">
                <div className="flex justify-between items-start mb-2">
                  <span className="text-xs font-black text-emerald-600">{item.date}</span>
                  <span className="font-black">₹{item.total}</span>
                </div>
                <p className="text-xs text-stone-500 italic">Deliver to: {item.address}</p>
                <div className="mt-2 flex flex-wrap gap-1">
                  {item.items.map((it, idx) => <span key={idx} className="bg-white px-2 py-0.5 rounded text-[9px] border border-stone-100">{it}</span>)}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

// --- MAIN APP ---
const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [userName, setUserName] = useState('');
  const [activeTab, setActiveTab] = useState('explore');
  const [loadingMarkets, setLoadingMarkets] = useState(false);
  const [cart, setCart] = useState<Product[]>([]);
  const [showCart, setShowCart] = useState(false);
  const [showAddressForm, setShowAddressForm] = useState(false);
  const [showPayment, setShowPayment] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [latestOrder, setLatestOrder] = useState<PurchaseHistoryItem | null>(null);
  const [showLocationPrompt, setShowLocationPrompt] = useState(false);
  const [deliveryAddress, setDeliveryAddress] = useState('');
  const [appReady, setAppReady] = useState(false);

  const [allFarmers, setAllFarmers] = useState<Farmer[]>([]);
  const [markets, setMarkets] = useState<Market[]>(MARKETS);
  const [products, setProducts] = useState<Product[]>([]);
  const [userStats, setUserStats] = useState<UserStats>({
    marketsVisited: 0,
    co2SavedKg: 0,
    localEconomySupport: 0,
    badgesEarned: 0
  });
  const [purchaseHistory, setPurchaseHistory] = useState<PurchaseHistoryItem[]>([]);

  useEffect(() => {
    const init = async () => {
      const session = await db.getSession();
      const farmers = await db.getFarmers();
      const items = await db.getProducts();
      setAllFarmers(farmers);
      setProducts(items);
      if (session) {
        setUserName(session.name);
        setIsLoggedIn(true);
        const stats = await db.getUserStats(session.name);
        const history = await db.getPurchaseHistory(session.name);
        setUserStats(stats);
        setPurchaseHistory(history);
      }
      setAppReady(true);
    };
    init();
  }, [activeTab]); // Refresh products when changing tabs

  const handleLogin = (name: string) => {
    setUserName(name);
    setIsLoggedIn(true);
    setShowLocationPrompt(true);
  };

  const handleLogout = async () => {
    await db.logout();
    setIsLoggedIn(false);
    setCart([]);
  };

  const handleLocationGrant = async (pos: GeolocationPosition) => {
    setShowLocationPrompt(false);
    setLoadingMarkets(true);
    const dynamicMarkets = await getNearbyMarkets(pos.coords.latitude, pos.coords.longitude);
    if (dynamicMarkets && dynamicMarkets.length > 0) {
      setMarkets(dynamicMarkets);
    }
    setLoadingMarkets(false);
  };

  const addToCart = (product: Product) => {
    setCart(prev => [...prev, product]);
  };

  const onPaymentSuccess = async () => {
    const total = cart.reduce((sum, p) => sum + p.price, 0);
    const order: PurchaseHistoryItem = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      date: new Date().toLocaleDateString('en-IN'),
      items: cart.map(p => p.name),
      total: total,
      address: deliveryAddress
    };

    const updatedHistory = await db.saveOrder(userName, order);
    const newStats = {
      ...userStats,
      localEconomySupport: userStats.localEconomySupport + total,
      co2SavedKg: userStats.co2SavedKg + (total * 0.05),
      marketsVisited: userStats.marketsVisited + 1
    };
    await db.saveUserStats(userName, newStats);

    setPurchaseHistory(updatedHistory);
    setUserStats(newStats);
    setLatestOrder(order);
    setShowPayment(false);
    setCart([]);
    setShowCart(false);
  };

  if (!appReady) return <div className="min-h-screen flex items-center justify-center text-emerald-900 font-black">Initializing HarvestHub...</div>;
  if (!isLoggedIn) return <Auth onLogin={handleLogin} />;

  const cartTotal = cart.reduce((sum, p) => sum + p.price, 0);

  return (
    <div className="min-h-screen md:pl-64 bg-stone-50">
      <Navigation activeTab={activeTab} setActiveTab={setActiveTab} onLogout={handleLogout} />

      <main className="max-w-7xl mx-auto p-6 md:p-12">
        <header className="flex justify-between items-center mb-10">
          <h2 className="text-3xl font-black text-stone-900">Namaste, {userName}</h2>
          <button 
            onClick={() => setShowCart(!showCart)}
            className="bg-white border border-stone-100 p-4 rounded-3xl shadow-lg relative"
          >
            <i className="fa-solid fa-bag-shopping text-emerald-600 text-xl"></i>
            {cart.length > 0 && <span className="absolute -top-2 -right-2 bg-red-500 text-white text-[10px] w-6 h-6 rounded-full flex items-center justify-center font-black">{cart.length}</span>}
          </button>
        </header>

        {activeTab === 'explore' && (
          <div className="space-y-12">
            <section>
              <h3 className="text-xl font-black text-stone-800 mb-6">Seasonal Harvest</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {products.filter(p => p.inSeason).map(product => (
                  <div key={product.id} className="bg-white rounded-[2rem] border border-stone-100 overflow-hidden shadow-sm flex flex-col hover:shadow-xl transition-all group">
                    <img src={product.image} className="h-40 w-full object-cover group-hover:scale-105 transition-transform duration-700" />
                    <div className="p-6 flex-1 flex flex-col">
                      <div className="flex justify-between items-start mb-2">
                        <h4 className="font-bold text-stone-800">{product.name}</h4>
                        <span className="text-[10px] font-black text-emerald-600 bg-emerald-50 px-2 py-0.5 rounded uppercase tracking-tighter">Fresh</span>
                      </div>
                      <p className="text-emerald-700 font-black mb-4">₹{product.price} / {product.unit}</p>
                      <button onClick={() => addToCart(product)} className="mt-auto w-full bg-stone-900 text-white font-black py-3 rounded-2xl text-xs hover:bg-emerald-600 transition-all">Add to Bag</button>
                    </div>
                  </div>
                ))}
              </div>
            </section>
          </div>
        )}

        {activeTab === 'farmers' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {allFarmers.map(farmer => <FarmerCard key={farmer.id} farmer={farmer} onAddToCart={addToCart} />)}
          </div>
        )}

        {activeTab === 'mystall' && <FarmerDashboard farmerName={userName} />}

        {activeTab === 'markets' && (
          <div className="space-y-8">
            <div className="bg-white p-6 rounded-3xl border border-stone-100 flex items-center gap-4">
              <div className="w-12 h-12 rounded-2xl bg-emerald-50 flex items-center justify-center text-emerald-600">
                <i className="fa-solid fa-location-arrow"></i>
              </div>
              <div>
                <p className="text-sm font-black text-stone-800">Markets Near You</p>
                <p className="text-xs text-stone-400">Discover real farmers' markets in your neighborhood.</p>
              </div>
            </div>
            {loadingMarkets ? (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {[1, 2].map(i => (
                  <div key={i} className="bg-stone-100 h-64 rounded-[2rem] animate-pulse"></div>
                ))}
              </div>
            ) : (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {markets.map(m => <MarketCard key={m.id} market={m} />)}
              </div>
            )}
          </div>
        )}

        {activeTab === 'kitchen' && <AIKitchen />}
        {activeTab === 'stats' && <ImpactStats stats={userStats} />}
      </main>

      {showCart && (
        <div className="fixed inset-y-0 right-0 w-full max-w-md bg-white shadow-2xl z-[1000] p-10 flex flex-col border-l border-stone-100 animate-in slide-in-from-right duration-300">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-2xl font-black">Shopping Bag</h3>
            <button onClick={() => setShowCart(false)}><i className="fa-solid fa-xmark"></i></button>
          </div>
          <div className="flex-1 overflow-y-auto space-y-4">
            {cart.map((item, idx) => (
              <div key={idx} className="flex justify-between items-center py-2 border-b border-stone-50">
                <span className="font-bold">{item.name}</span>
                <span className="font-black">₹{item.price}</span>
              </div>
            ))}
            {cart.length === 0 && <p className="text-center py-20 text-stone-400 font-bold">Your bag is empty.</p>}
          </div>
          <div className="mt-8 pt-8 border-t border-stone-100">
            <div className="flex justify-between mb-8">
              <span className="font-black text-stone-500">Total</span>
              <span className="font-black text-2xl text-emerald-700">₹{cartTotal}</span>
            </div>
            <button 
              disabled={cart.length === 0}
              onClick={() => setShowAddressForm(true)} 
              className="w-full bg-emerald-600 text-white font-black py-5 rounded-3xl hover:bg-emerald-700 disabled:opacity-50"
            >
              Checkout
            </button>
          </div>
        </div>
      )}

      {showLocationPrompt && <LocationPrompt onGrant={handleLocationGrant} onSkip={() => setShowLocationPrompt(false)} />}
      {showAddressForm && <AddressForm total={cartTotal} onProceed={(addr) => { setDeliveryAddress(addr); setShowAddressForm(false); setShowPayment(true); }} onCancel={() => setShowAddressForm(false)} />}
      {showPayment && <PaymentGateway total={cartTotal} onCancel={() => setShowPayment(false)} onSuccess={onPaymentSuccess} />}
      {latestOrder && <Invoice order={latestOrder} userName={userName} onClose={() => setLatestOrder(null)} />}
      {showHistory && <HistoryModal history={purchaseHistory} onClose={() => setShowHistory(false)} />}

      <button onClick={() => setShowHistory(true)} className="fixed bottom-24 right-6 bg-stone-900 text-white p-4 rounded-full shadow-2xl z-40 md:hidden">
        <i className="fa-solid fa-clock-rotate-left"></i>
      </button>
    </div>
  );
};

export default App;
